// ── Switch Mode ─────────────────────────────
const item = $input.first().json.body ?? $input.first().json;
const mode = (item.mode ?? 'generate').trim();
return [{ json: { ...item, _mode: mode } }];

// ═══════════════════════════════════════════════════════════
// TASK LOADER — Charge la config pour le mode task
// Lit .blackstaff/index.md + context.md
// Construit le payload standard depuis la description de tâche
// ═══════════════════════════════════════════════════════════
const fs = require('fs');
const item = $input.first().json;

if (!item.project) throw new Error('[TASK] Champ obligatoire manquant : "project"');

function parseScalar(val) {
  val = val.trim();
  if (val === 'true')  return true;
  if (val === 'false') return false;
  if (val === 'null' || val === '~' || val === '') return null;
  if (/^["'].*["']$/.test(val)) return val.slice(1, -1);
  if (/^-?\d+(\.\d+)?$/.test(val)) return Number(val);
  return val;
}

function parseSimpleYaml(yamlStr) {
  const lines = yamlStr.split('\n').filter(l => !/^\s*#/.test(l) && l.trim() !== '');
  let i = 0;

  function getIndent(line) { return line.match(/^ */)[0].length; }

  function parseBlock(indent) {
    const isList = i < lines.length && getIndent(lines[i]) === indent && lines[i].trim().startsWith('- ');

    if (isList) {
      const arr = [];
      while (i < lines.length && getIndent(lines[i]) === indent && lines[i].trim().startsWith('- ')) {
        const content = lines[i].trim().slice(2);
        const kv = content.match(/^([\w.-]+)\s*:\s*(.*)$/);
        if (kv) {
          const obj = {};
          i++;
          if (kv[2].trim() === '') {
            obj[kv[1]] = (i < lines.length && getIndent(lines[i]) > indent) ? parseBlock(getIndent(lines[i])) : null;
          } else {
            obj[kv[1]] = parseScalar(kv[2]);
          }
          // Clés additionnelles indentées appartenant au même item de liste
          while (i < lines.length && getIndent(lines[i]) > indent && !lines[i].trim().startsWith('- ')) {
            const kv2 = lines[i].trim().match(/^([\w.-]+)\s*:\s*(.*)$/);
            if (!kv2) { i++; continue; }
            i++;
            if (kv2[2].trim() === '') {
              obj[kv2[1]] = (i < lines.length && getIndent(lines[i]) > indent) ? parseBlock(getIndent(lines[i])) : null;
            } else {
              obj[kv2[1]] = parseScalar(kv2[2]);
            }
          }
          arr.push(obj);
        } else {
          arr.push(parseScalar(content));
          i++;
        }
      }
      return arr;
    }

    const obj = {};
    while (i < lines.length && getIndent(lines[i]) === indent) {
      const kv = lines[i].trim().match(/^([\w.-]+)\s*:\s*(.*)$/);
      if (!kv) { i++; continue; }
      const key = kv[1];
      const val = kv[2].trim();
      i++;
      if (val === '') {
        obj[key] = (i < lines.length && getIndent(lines[i]) > indent) ? parseBlock(getIndent(lines[i])) : null;
      } else if (val === '[]') {
        obj[key] = [];
      } else {
        obj[key] = parseScalar(val);
      }
    }
    return obj;
  }

  return parseBlock(0);
}

// ── Lire les fichiers ────────────────────────────────────────
const projectBasePath = `/home/node/projets/${item.project}`;
const configPath  = `${projectBasePath}/.blackstaff/index.md`;
const contextPath = `${projectBasePath}/.blackstaff/context.md`;

let projectConfig  = null;
let projectContext = null;

if (fs.existsSync(configPath)) {
  const raw = fs.readFileSync(configPath, 'utf8');
  const fm  = raw.match(/^---\n([\s\S]*?)\n---/);
  if (fm) { try { projectConfig = parseSimpleYaml(fm[1]); } catch(e) {} }
}

if (fs.existsSync(contextPath)) {
  const raw = fs.readFileSync(contextPath, 'utf8');
  const fm  = raw.match(/^---\n[\s\S]*?\n---\n([\s\S]*)$/);
  projectContext = fm ? fm[1].trim() : raw.trim();
}

// ── Modèle de domaine — mémoire des ressources déjà construites ──
// (propre au PROJET, mis à jour automatiquement après chaque tâche
// clôturée par l'extension — voir _updateDomainModel côté TaskWorkflow)
const domainModelPath = `${projectBasePath}/.blackstaff/domain-model.md`;
let domainModel = null;
if (fs.existsSync(domainModelPath)) {
  domainModel = fs.readFileSync(domainModelPath, 'utf8').trim();
}

// ── Déduire side + framework depuis la stack ────────────
const stack   = projectConfig?.stack ?? {};
const hasFront = !!stack.frontend;
const hasBack  = !!stack.backend;
const side     = hasFront && hasBack ? 'both' : (hasFront ? 'frontend' : 'backend');
const framework = hasFront
  ? (stack.frontend?.framework ?? 'nuxt')
  : (stack.backend?.framework  ?? 'rails');

// ── Spec = titre + description de la tâche ───────────
const spec = [
  `# ${item.taskSubject || 'Tâche #' + item.taskId}`,
  '',
  item.taskDescription ?? '',
].join('\n').trim();

return [{
  json: {
    project:        item.project,
    pattern:        'task',
    patternKey:     'task',
    side,
    framework,
    spec,
    options:        { taskMode: true, taskId: item.taskId, taskSubject: item.taskSubject },
    anthropicApiKey: item.anthropicApiKey ?? '',
    projectConfig,
    projectContext,
    frontendContext: hasFront ? stack.frontend : null,
    backendContext:  hasBack  ? stack.backend  : null,
    stack,
    projectBasePath,
    configLoaded:   !!projectConfig,
    contextLoaded:  !!projectContext,
    resolvedMarkdownContext: null,
    // ── Un seul fichier par appel — fourni par l'extension ──
    currentFile: item.currentFile ?? null,  // { path, description, index, total }
    existingContent: item.existingContent ?? null,  // contenu du fichier s'il existe déjà (fusion)
    mergePolicy: item.mergePolicy ?? null,  // 'additive' : 07m remet les lignes existantes altérées (2026-10-02)
    // ── Enrichissement de la liste de fichiers (mode contracts) ──
    step:        item.step ?? 'generate',   // 'contracts' | 'generate'
    fileList:    item.fileList ?? null,       // [{ path, description }] déjà connu (regex extension)
    contracts:        item.contracts ?? null,        // exports déclarés des autres fichiers
    generatedContent: item.generatedContent ?? null,  // contenu à vérifier (step='local-review')
    correctionNotes:  item.correctionNotes ?? null,   // notes de correction (retry local ou Claude sans code)
    // ── step='generate-tests' ── liste des fichiers deja generes envoyee par
    // l'extension (voir TaskWorkflow.ts _generateTests) -- SANS cette ligne,
    // 04f0 recevait toujours generatedFiles=undefined et renvoyait
    // silencieusement _splitEmpty=true a chaque appel (aucun test jamais
    // genere, aucune erreur visible cote extension ni cote n8n).
    generatedFiles: item.generatedFiles ?? null,
    domainModel,       // mémoire des ressources déjà construites sur ce projet
  }
}];

// ═══════════════════════════════════════════════════════════
// 03 · Context Resolver (unifié — generate + task, 3 niveaux)
// + squelettes par type de fichier + suivi de liens markdown borné
// + mémoire projet (.blackstaff/memory.json → existingCapabilities)
// ═══════════════════════════════════════════════════════════
const fs   = require('fs');
const path = require('path');

const item = $input.first().json;
const { stack, side, spec, pattern, currentFile } = item;

const BLACKSTAFF_ROOT = `/home/node/projets/blackstaff/`;
const patternsRoot    = path.join(BLACKSTAFF_ROOT, 'patterns');
const learnedRoot     = path.join(patternsRoot, '_learned');
const frameworksRoot  = path.join(BLACKSTAFF_ROOT, 'frameworks');
const skeletonsRoot   = path.join(BLACKSTAFF_ROOT, 'skeletons');
const learnedExamplesRoot = path.join(patternsRoot, '_learned', 'examples');

function readFile(p) { return (p && fs.existsSync(p)) ? fs.readFileSync(p, 'utf8') : null; }

// ── Suivi de liens markdown — UNE seule profondeur, dédupliqué ────────
// [texte](chemin/relatif.md) → inclut le contenu du fichier lié, une
// seule fois, sans jamais redescendre plus loin (évite l'explosion de
// contexte qui nuirait à un petit modèle).
function followLinks(content, baseDir, visited) {
  if (!content) return content;
  const linkRegex = /\[([^\]]*)\]\(([^)]+\.md)\)/g;
  let result = content;
  let match;
  const seenHere = new Set();

  while ((match = linkRegex.exec(content)) !== null) {
    const relPath = match[2];
    if (seenHere.has(relPath)) { continue; }
    seenHere.add(relPath);

    const resolved = path.resolve(baseDir, relPath);
    // Sécurité : rester dans l'arbre blackstaff, pas de sortie via ../../..
    if (!resolved.startsWith(BLACKSTAFF_ROOT)) { continue; }
    if (visited.has(resolved)) { continue; } // déjà inclus ailleurs, pas de doublon
    if (!fs.existsSync(resolved)) { continue; }

    visited.add(resolved);
    const linked = fs.readFileSync(resolved, 'utf8');
    result += `\n\n> ↳ Référencé par [${match[1]}](${relPath}) :\n\n${linked}`;
  }
  return result;
}

function declaredPatterns(stackConfig) { return stackConfig?.patterns ?? []; }

// Scanne un dossier de patterns (déclarés OU appris) à la recherche de tags
// correspondant au texte donné — mutualisé pour patterns/ et patterns/_learned/.
function scanTagsInDir(root, textLower) {
  if (!fs.existsSync(root)) return [];
  const slugs = fs.readdirSync(root).filter(d =>
    d !== '_learned' && fs.existsSync(path.join(root, d, 'index.md'))
  );
  const matches = [];
  for (const slug of slugs) {
    const idx = readFile(path.join(root, slug, 'index.md'));
    const tagsMatch = idx?.match(/tags:\s*\[(.*?)\]/i);
    const tags = tagsMatch
      ? tagsMatch[1].split(',').map(t => t.trim().replace(/["']/g, '').toLowerCase()).filter(Boolean)
      : [];
    // Mot entier (Unicode), pas sous-chaîne : « auth » déclenchait le pattern auth sur « authentifiée »
    // / « authentication » (28 requêtes sur 60 le 2026-10-01, dont toute request spec qui teste un 401),
    // « liste » le pattern crud sur « listes ».
    const isWord = (tag) => new RegExp(`(?<![\\p{L}\\p{N}_])${tag.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?![\\p{L}\\p{N}_])`, 'u').test(textLower);
    if (tags.some(tag => tag.length > 2 && isWord(tag))) { matches.push(slug); }
  }
  return matches;
}

// Détection par mots-clés — scanne à la fois les patterns DÉCLARÉS (patterns/,
// leurs propres tags peuvent aussi déclencher une détection automatique) et les
// patterns APPRIS (patterns/_learned/, sans dossier réel ailleurs).
function learnedPatternMatch(text) {
  const textLower = (text ?? '').toLowerCase();
  const fromDeclared = scanTagsInDir(patternsRoot, textLower);
  const fromLearned  = scanTagsInDir(learnedRoot, textLower);
  return [...new Set([...fromDeclared, ...fromLearned])];
}

function resolveVersionFile(framework, requestedVersion) {
  if (!requestedVersion) return null;
  const major = String(requestedVersion).split('.')[0];
  // ── OKF (nouveau format, migre framework par framework — nuxt migre le
  // 2026-08-14) essaye d'abord, fallback sur l'ancien frameworksRoot pour les
  // frameworks pas encore migres (rails/laravel/symfony au 2026-08-21) ──
  const roots = [path.join(BLACKSTAFF_ROOT, 'okf', 'frameworks'), frameworksRoot];
  for (const root of roots) {
    const versionDir = path.join(root, framework);
    if (!fs.existsSync(versionDir)) continue;
    const exact = path.join(versionDir, `v${major}.md`);
    if (fs.existsSync(exact)) return exact;
    const avail = fs.readdirSync(versionDir)
      .filter(f => /^v\d+\.md$/.test(f))
      .map(f => parseInt(f.match(/^v(\d+)\.md$/)[1], 10))
      .filter(v => v <= parseInt(major, 10)).sort((a, b) => b - a);
    if (avail.length) return path.join(versionDir, `v${avail[0]}.md`);
  }
  return null;
}

function findRecipe(patternDir, framework, sideDir) {
  const dir = path.join(patternDir, 'recipes', sideDir);
  if (!fs.existsSync(dir)) return { found: false, reason: `dossier recipes/${sideDir} introuvable dans ${patternDir}` };
  const c = fs.readdirSync(dir).filter(f => f.startsWith(`${framework}-`) && f.endsWith('.md'));
  if (c.length === 0) return { found: false, reason: `aucun fichier "${framework}-*.md" dans ${dir}` };
  return { found: true, path: path.join(dir, c[0]) };
}

// ── Dépendances déclarées par un pattern (dependencies.json optionnel) ──
function loadTaskTemplate(patternDir) {
  const p = path.join(patternDir, 'task-template.md');
  return fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : null;
}

function loadDependencies(patternDir) {
  const depPath = path.join(patternDir, 'dependencies.json');
  if (!fs.existsSync(depPath)) return { npm: [], composer: [], gem: [] };
  try {
    const parsed = JSON.parse(fs.readFileSync(depPath, 'utf8'));
    return { npm: parsed.npm ?? [], composer: parsed.composer ?? [], gem: parsed.gem ?? [] };
  } catch (e) {
    return { npm: [], composer: [], gem: [] };
  }
}

function mergeDependencies(a, b) {
  return {
    npm:      [...new Set([...(a.npm ?? []), ...(b.npm ?? [])])],
    composer: [...new Set([...(a.composer ?? []), ...(b.composer ?? [])])],
    gem:      [...new Set([...(a.gem ?? []), ...(b.gem ?? [])])],
  };
}

// ── Liste noire d'imports/APIs connus pour être mal utilisés par le modèle ──
// (forbidden.json optionnel dans le dossier du pattern) — injectée dans le
// prompt ET vérifiée structurellement, pour bloquer AVANT que ça se reproduise
// sur plusieurs fichiers du même type dans une même tâche.
function loadForbidden(patternDir) {
  const p = path.join(patternDir, 'forbidden.json');
  if (!fs.existsSync(p)) return [];
  try { return JSON.parse(fs.readFileSync(p, 'utf8')); }
  catch (e) { return []; }
}

function mergeForbidden(a, b) {
  const seen = new Set(a.map(f => f.name));
  const merged = [...a];
  for (const f of b) { if (!seen.has(f.name)) { merged.push(f); seen.add(f.name); } }
  return merged;
}

function loadPatternContextDebug(patternKey, framework, sideKey, visited) {
  const attempts = [];
  for (const [rootLabel, root] of [['patterns', patternsRoot], ['_learned', learnedRoot]]) {
    const dir = path.join(root, patternKey);
    if (!fs.existsSync(dir)) {
      attempts.push({ location: rootLabel, path: dir, ok: false, reason: 'dossier introuvable' });
      continue;
    }
    const idxPath = path.join(dir, 'index.md');
    const idxOk = fs.existsSync(idxPath);
    const recipeResult = findRecipe(dir, framework, sideKey);
    const dependencies = loadDependencies(dir);
    const forbidden = loadForbidden(dir);
    const taskTemplate = loadTaskTemplate(dir);

    const parts = [];
    if (idxOk) {
      visited.add(idxPath);
      parts.push(`## Pattern : ${patternKey}\n\n${followLinks(readFile(idxPath), dir, visited)}`);
    }
    if (recipeResult.found) {
      visited.add(recipeResult.path);
      parts.push(`## Recipe : ${patternKey} avec ${framework}\n\n${followLinks(readFile(recipeResult.path), path.dirname(recipeResult.path), visited)}`);
    }

    attempts.push({
      location: rootLabel, path: dir,
      ok: idxOk || recipeResult.found,
      indexMd: idxOk ? 'trouvé' : 'absent',
      recipe: recipeResult.found ? `trouvée (${recipeResult.path})` : `absente — ${recipeResult.reason}`,
      dependencies: (dependencies.npm.length + dependencies.composer.length + dependencies.gem.length) > 0 ? dependencies : null,
      forbidden: forbidden.length > 0 ? forbidden.map(f => f.name) : null,
      taskTemplate: !!taskTemplate,
    });

    if (parts.length) { return { context: parts.join('\n\n'), attempts, dependencies, forbidden, taskTemplate }; }
  }
  return { context: null, attempts, dependencies: { npm: [], composer: [], gem: [] }, forbidden: [], taskTemplate: null };
}

// ── Squelette par type de fichier — donne une coquille concrète à ────
// remplir plutôt que de laisser le modèle inventer la structure.
// ── Dérivation déterministe de fileType — même logique de pattern de
// chemin que 03f (verbe HTTP + segment dynamique / nom de fichier), pour
// que le squelette se charge automatiquement même si l'appelant n'a pas
// pensé à fournir currentFile.fileType explicitement. Une valeur fournie
// explicitement par l'appelant reste toujours prioritaire.
function deriveFileType(cf) {
  const p = cf?.path ?? '';
  if (!p) return null;
  const isAuthEndpoint = /server\/api\/auth\//i.test(p);
  const apiMatch = !isAuthEndpoint ? p.match(/server\/api\/.+\.(get|post|put|patch|delete)\.(ts|js)$/i) : null;
  if (apiMatch) {
    const verb = apiMatch[1].toLowerCase();
    const isDetail = /\[[^/\]]+\]\.\w+\.(ts|js)$/i.test(p);
    if (verb === 'get' && isDetail) return 'route-show-get';
    if (verb === 'get') return 'route-index-get';
    if (verb === 'post') return 'route-create-post';
    if (verb === 'patch' || verb === 'put') return 'route-update-patch';
    if (verb === 'delete') return 'route-delete';
  }
  if (p.endsWith('.vue')) {
    if (/\/create\.vue$/i.test(p)) return 'page-create';
    if (/\[[^/\]]+\]\/edit\.vue$/i.test(p) || /\/edit\.vue$/i.test(p)) return 'page-edit';
    if (/\[[^/\]]+\]\.vue$/i.test(p)) return 'page-detail';
    if (/\/index\.vue$/i.test(p)) return 'page-list';
  }
  if (/composables?\/use[A-Z]/i.test(p)) return 'composable';
  if (/middleware\//i.test(p) && p.endsWith('.ts')) return 'middleware';
  return null;
}

function loadSkeleton(framework, fileType, visited) {
  if (!framework || !fileType) return null;
  const skelPath = path.join(skeletonsRoot, framework, `${fileType}.md`);
  if (!fs.existsSync(skelPath)) return null;
  visited.add(skelPath);
  return followLinks(readFile(skelPath), path.dirname(skelPath), visited);
}

// ── Exemples appris (corrections Claude capitalisées) — le plus récent ──
// pour ce (framework, fileType), en complément du squelette générique.
function loadLearnedExample(framework, fileType) {
  if (!framework || !fileType) return null;
  const dir = path.join(learnedExamplesRoot, framework, fileType);
  if (!fs.existsSync(dir)) return null;
  const files = fs.readdirSync(dir)
    .filter(f => f.endsWith('.md'))
    .map(f => ({ name: f, mtime: fs.statSync(path.join(dir, f)).mtimeMs }))
    .sort((a, b) => b.mtime - a.mtime);
  if (files.length === 0) return null;
  return readFile(path.join(dir, files[0].name));
}

// ── Mémoire projet — .blackstaff/memory.json → builtCapabilities ────────
// Fichier situé dans le PROJET (pas dans le bundle blackstaff), écrit côté
// extension par TaskWorkflow.ts (_updateBuiltCapabilities) après chaque
// clôture de tâche. Filtré aux entités mentionnées dans `spec` — évite de
// gonfler le prompt avec TOUTES les entités du projet à chaque tâche, alors
// que seules quelques-unes sont potentiellement concernées par celle-ci.
function loadExistingCapabilities(projectBasePath, specText) {
  if (!projectBasePath || !specText) return null;
  const memPath = path.join(projectBasePath, '.blackstaff', 'memory.json');
  if (!fs.existsSync(memPath)) return null;

  let memory;
  try {
    memory = JSON.parse(fs.readFileSync(memPath, 'utf8'));
  } catch (e) {
    return null; // memory.json corrompu — on ignore plutôt que de planter la résolution
  }

  const builtCapabilities = memory.builtCapabilities ?? {};
  const specLower = specText.toLowerCase();
  const filtered = {};

  for (const [entity, cap] of Object.entries(builtCapabilities)) {
    const entityLower = entity.toLowerCase();
    // Matching simple sous-chaîne, tolère le pluriel anglais basique — cohérent
    // avec le mécanisme de détection de pattern par tags déjà utilisé plus haut.
    if (specLower.includes(entityLower) || specLower.includes(`${entityLower}s`)) {
      filtered[entity] = cap;
    }
  }

  return Object.keys(filtered).length > 0 ? filtered : null;
}

function resolveForSide(sideKey, stackConfig, visited) {
  const debug = { sideKey, stackConfigType: typeof stackConfig, stackConfigRaw: stackConfig, candidates: [] };

  if (!stackConfig || typeof stackConfig !== 'object') {
    debug.reason = `stack.${sideKey} est ${JSON.stringify(stackConfig)} (type: ${typeof stackConfig})`;
    return { result: null, debug };
  }

  const { framework, version } = stackConfig;
  const level1 = declaredPatterns(stackConfig);
  const level2 = learnedPatternMatch(spec);
  const explicit = pattern ? [pattern] : [];
  // Test files (spec/**/*_spec.rb, *.spec.ts, *.test.ts): the `tests` pattern goes FIRST (the prompt
  // used to cut this context at 6000 chars; 32000 since 2026-10-01) and `crud` is dropped — its
  // recipes are application code and pushed Blackstaff to mock everything in specs (2026-09-29).
  const isTestFile = /(^|\/)spec\/.+_spec\.rb$|\.(spec|test)\.[jt]s$/.test(String(currentFile?.path ?? ''));
  const patternKeys = isTestFile
    ? [...new Set(['tests', ...explicit, ...level1, ...level2])].filter(k => k !== 'crud')
    : [...new Set([...explicit, ...level1, ...level2])];
  debug.testFile = isTestFile;

  debug.declaredPatterns = level1;
  debug.learnedMatches = level2;
  debug.explicitPattern = explicit;
  debug.frameworkResolved = framework ?? null;

  const parts = [];
  const used  = [];
  let dependencies = { npm: [], composer: [], gem: [] };
  let forbidden = [];
  const taskTemplates = [];
  for (const key of patternKeys) {
    const { context, attempts, dependencies: patternDeps, forbidden: patternForbidden, taskTemplate } = loadPatternContextDebug(key, framework, sideKey, visited);
    debug.candidates.push({ patternKey: key, found: !!context, attempts });
    if (context) {
      parts.push(context);
      used.push(key);
      dependencies = mergeDependencies(dependencies, patternDeps);
      forbidden = mergeForbidden(forbidden, patternForbidden ?? []);
      if (taskTemplate) { taskTemplates.push({ patternKey: key, template: taskTemplate }); }
    }
  }

  const fwPath = path.join(frameworksRoot, `${framework}.md`);
  if (fs.existsSync(fwPath)) { visited.add(fwPath); parts.push(`## Conventions ${framework}\n\n${followLinks(readFile(fwPath), frameworksRoot, visited)}`); }
  const vfPath = resolveVersionFile(framework, version);
  if (vfPath) { visited.add(vfPath); parts.push(`## Conventions ${framework} v${version}\n\n${followLinks(readFile(vfPath), path.dirname(vfPath), visited)}`); }

  debug.frameworkConventionsFound = fs.existsSync(fwPath);

  // ── Liste noire au niveau FRAMEWORK — s'applique à TOUS les patterns ────
  // (frameworks/{framework}/forbidden.json), fusionnée avec celle des patterns.
  const frameworkForbiddenDir = path.join(frameworksRoot, framework);
  const frameworkForbidden = fs.existsSync(frameworkForbiddenDir) ? loadForbidden(frameworkForbiddenDir) : [];
  forbidden = mergeForbidden(forbidden, frameworkForbidden);
  debug.frameworkForbiddenCount = frameworkForbidden.length;

  // ── Dépendances au niveau FRAMEWORK — s'appliquent à TOUS les patterns ──
  // (frameworks/{framework}/dependencies.json), fusionnées avec celles des patterns.
  const frameworkDeps = fs.existsSync(frameworkForbiddenDir) ? loadDependencies(frameworkForbiddenDir) : { npm: [], composer: [], gem: [] };
  dependencies = mergeDependencies(dependencies, frameworkDeps);
  debug.frameworkDependenciesCount = frameworkDeps.npm.length + frameworkDeps.composer.length + frameworkDeps.gem.length;

  // Squelette du fichier courant (génération unitaire uniquement)
  let skeleton = null;
  let learnedExample = null;
  // ⚠️ deriveFileType() (pattern de chemin exact, ex: "page-list",
  // "route-index-get") a PRIORITÉ sur currentFile.fileType envoyé par
  // l'extension — celle-ci envoie TOUJOURS une valeur générique
