    learnedExample = loadLearnedExample(framework, effectiveFileType);
    debug.learnedExampleFound = !!learnedExample;
  }

  return {
    result: { sideKey, framework, version, patternsUsed: used, context: parts.join('\n\n---\n\n'), skeleton, learnedExample, dependencies, forbidden, taskTemplates },
