const nuxtVersion = String(item.frontendContext?.version ?? '').replace(/[^0-9]/g, '');
if (nuxtVersion === '4') {
  const FRONTEND_DIRS = /^(pages|components|layouts|middleware|plugins)\//;
  for (const f of files) {
    if (!f.path) continue;
    if (FRONTEND_DIRS.test(f.path) && !f.path.startsWith('app/')) {
      f._contractViolations = f._contractViolations ?? [];
      f._contractViolations.push(
        `Fichier "${f.path}" généré hors de app/ alors que nuxtVersion=4 — ` +
        `devrait être "app/${f.path}" (voir okf/frameworks/nuxt/v4.md).`
      );
    }
  }
}

// ── Validation pilotée par contrat — backendAuthSheet (03e) ──
// Un endpoint d'authentification qui n'appelle PAS le chemin backend
// EXACT déclaré dans la fiche résolue (pas un chemin halluciné plausible)
// est bloqué ici, avant même la revue Claude — le contrat est un FAIT,
// pas une suggestion que le modèle peut réinterpréter.
const authSheet = item.backendAuthSheet;
if (authSheet?.endpoints) {
  const AUTH_FILE_PATTERNS = {
    login:    /login|sign.?in/i,
    register: /register|sign.?up/i,
    logout:   /logout|sign.?out/i,
  };
  for (const f of files) {
    if (!f.path || !f.content || !/server\/api\//.test(f.path)) continue;
    for (const [action, matcher] of Object.entries(AUTH_FILE_PATTERNS)) {
      if (!matcher.test(f.path)) continue;
      const expected = authSheet.endpoints[action];
      if (!expected?.path) continue;
      if (!f.content.includes(expected.path)) {
        f._contractViolations = f._contractViolations ?? [];
        f._contractViolations.push(
          `Endpoint "${action}" attendu vers le backend : ${expected.method} ${expected.path} ` +
          `(fiche ${authSheet.library ?? authSheet.framework}) — chemin absent du fichier généré, ` +
          `possible URL backend inventée au lieu de la fiche de référence.`
        );
      }
    }
  }
}

// ── Garde-fou déterministe — un petit modèle recopie parfois le chemin
// du fichier serveur qu'il vient d'écrire au lieu d'appliquer la règle
// de routing Nuxt (ex: $fetch('/server/api/articles/index.get.ts') au
// lieu de $fetch('/api/articles')). Auto-fix par regex plutôt que de
// compter sur le prompt seul — filet de sécurité, la vraie prévention
// est l'injection de la table de routage en amont (04c/05t).
const badServerFetchRegex = /(\$fetch|useFetch)\(\s*(['"`])\/server\/api\/([^'"`]+?)\.(get|post|put|delete|patch)\.(ts|js)\2/gi;
for (const f of files) {
  if (!f.content) continue;
  if (badServerFetchRegex.test(f.content)) {
    f.content = f.content.replace(badServerFetchRegex, (m, fn, quote, route, method) => {
      let cleanRoute = route.replace(/\/index$/, '');
      if (cleanRoute === 'index') cleanRoute = '';
      cleanRoute = cleanRoute.replace(/\[([^\]]+)\]/g, ':$1');
      const url = ('/api/' + cleanRoute).replace(/\/+$/, '') || '/api';
      return `${fn}(${quote}${url}${quote}`;
    });
    f._apiUrlAutoFixed = true;
  }
}

// ── Contrôle local (gratuit, sans LLM) — attrape les violations de forme
// évidentes AVANT d'arriver jusqu'à la revue Claude (coûteuse en tokens).
function localSanityCheck(file) {
  if (!file || !file.content) { return { ok: false, reason: 'Contenu vide' }; }
  const c = file.content;
  const p = file.path ?? '';
  // ── Liste noire du pattern (forbidden.json) — bloque structurellement,
  // sans dépendre de Claude, une classe entière d'erreurs qui se répète
  // sur plusieurs fichiers d'une même tâche (ex: axios réutilisé partout).
  const forbiddenList = item.forbidden ?? [];
  for (const f of forbiddenList) {
    const escaped = f.name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const importRegex = new RegExp(`(from\\s+['"]${escaped}['"]|require\\(['"]${escaped}['"]\\)|import\\s+['"]${escaped}['"])`);
    if (importRegex.test(c)) {
      return { ok: false, reason: `Import interdit détecté : "${f.name}" — ${f.reason}. Utilise à la place : ${f.useInstead}` };
    }
  }

  // ── Code hypothétique / placeholder au lieu d'une vraie implémentation ──
  const hypotheticalMarkers = /dans un (contexte|scénario) réel|fonction hypothétique|à remplacer par|placeholder\s*:|todo\s*:|fixme\s*:|ceci serait|se ferait en fonction/i;
  if (hypotheticalMarkers.test(c)) {
    return { ok: false, reason: 'Code hypothétique/placeholder détecté (commentaire décrivant la logique au lieu de l\'implémenter réellement)' };
  }
  if (p.endsWith('.vue')) {
    if (!/<template[\s>]/.test(c)) { return { ok: false, reason: 'Fichier .vue sans balise <template> — structure SFC invalide' }; }
    if (!/<script[\s>]/.test(c))   { return { ok: false, reason: 'Fichier .vue sans balise <script> — structure SFC invalide' }; }
    if (/<script\s+setup/.test(c) && /\bthis\.\w/.test(c)) {
      return { ok: false, reason: 'Usage de "this." dans un <script setup> — mélange invalide Options API / Composition API' };
    }
  }
  if (/\.ts$|\.js$/.test(p) && !p.endsWith('.d.ts')) {
    const openBraces  = (c.match(/\{/g)  || []).length;
    const closeBraces = (c.match(/\}/g)  || []).length;
    if (Math.abs(openBraces - closeBraces) > 1) {
      return { ok: false, reason: `Accolades déséquilibrées (${openBraces} ouvrantes / ${closeBraces} fermantes) — code probablement tronqué ou invalide` };
    }
  }
  // Cohérence avec le squelette imposé, si un squelette a été fourni pour ce type
  const skeletonMarkers = {
    'store':        ['defineStore'],
    'middleware':   ['defineNuxtRouteMiddleware'],
    'server-api':   ['defineEventHandler'],
    'config':       ['defineNuxtConfig'],
    'composable':   ['export function', 'export const'],
  };
  const fileTypeKey = item.currentFile?.fileType;
  if (fileTypeKey && skeletonMarkers[fileTypeKey]) {
    const hasMarker = skeletonMarkers[fileTypeKey].some(m => c.includes(m));
    if (!hasMarker) {
      return { ok: false, reason: `Marqueur attendu absent pour un fichier de type "${fileTypeKey}" (ex: ${skeletonMarkers[fileTypeKey][0]})` };
    }
  }
  return { ok: true, reason: '' };
}
// ── Score de qualité (0-100), par fichier — même principe que les
// signaux déjà collectés, juste pondérés au lieu d'un simple ok/false.
// Objectif : donner au client de quoi construire un récap (par fichier
// ET global) sans avoir à ré-analyser le code lui-même. N'ajoute AUCUNE
// détection nouvelle — pondère ce que localSanityCheck/detectIssues/le
// garde-fou de contrat ont déjà trouvé.
const SCORE_PENALTIES = {
  contractViolation: 20,   // par violation (URL backend fausse, chemin Nuxt 4 hors app/, etc.)
  apiUrlAutoFixed: 10,     // auto-corrigé = symptôme réel, même réparé
  localCheckFailed: 30,    // placeholder/import interdit/SFC invalide/accolades déséquilibrées
};
function computeFileScore(file, localCheckFailedForThisFile) {
  let score = 100;
  const violations = file._contractViolations ?? [];
  score -= violations.length * SCORE_PENALTIES.contractViolation;
  if (file._apiUrlAutoFixed) score -= SCORE_PENALTIES.apiUrlAutoFixed;
  if (localCheckFailedForThisFile) score -= SCORE_PENALTIES.localCheckFailed;
  return Math.max(0, Math.min(100, score));
}

let localCheckOk = true;
let localCheckReason = '';
if (item.currentFile && files.length > 0) {
  const check = localSanityCheck(files[0]);
  localCheckOk = check.ok;
  localCheckReason = check.reason;
  const violations = files[0]._contractViolations ?? [];
  if (localCheckOk && violations.length > 0) {
    localCheckOk = false;
    localCheckReason = violations[0];
  }
}

// Score par fichier — localSanityCheck tourne sur CHAQUE fichier, dans
// les DEUX modes (avant : seul files[0] en mode task était vérifié, les
// fichiers du mode bulk n'étaient jamais passés par ce check du tout —
// un placeholder dans un fichier bulk passait inaperçu). Le champ
// top-level localCheckOk/localCheckReason garde son sens d'origine
// (déclenche le retry en mode task) — ce check par fichier ici sert
// UNIQUEMENT au score, ne change pas le comportement de retry existant.
for (let i = 0; i < files.length; i++) {
  const perFileCheck = localSanityCheck(files[i]);
  const failedLocalCheck = !perFileCheck.ok;
  if (failedLocalCheck && !files[i]._contractViolations) {
    files[i]._localCheckReason = perFileCheck.reason; // visible même sans violation de contrat
  }
  files[i]._qualityScore = computeFileScore(files[i], failedLocalCheck);
}
const globalQualityScore = files.length > 0
  ? Math.round(files.reduce((sum, f) => sum + f._qualityScore, 0) / files.length)
  : null;
const filesBelowThreshold = files.filter(f => f._qualityScore < 70).map(f => ({ path: f.path, score: f._qualityScore }));

const issues = detectIssues(files, rawOutput);
// Échecs silencieux mesurés le 2026-10-01 (rejeu 234ce9c) : réponse sans bloc de code renvoyée avec
// error: null, et fichier existant renvoyé inchangé avec filesWritten: 1. Les deux deviennent une erreur
// explicite ; un fichier inchangé n'est pas réécrit.
let generationError = null;
const sameAsExisting = (a, b) => {
  const norm = (t) => (t ?? '').replace(/^\s*(#|\/\/)\s*\S+\.\w+\s*\n/, '').replace(/\s+/g, ' ').trim();
  return norm(a) === norm(b);
};
if (options.taskMode && item.currentFile && (files.length === 0 || !(files[0].content ?? '').trim())) {
  // bloc absent OU bloc vide (vu 2026-10-01 sur le ticket #88 : filesWritten 1, error null, contenu vide —
  // avec existingContent, l'écrivain aurait remplacé le vrai fichier par un fichier vide)
  generationError = 'empty_generation: la réponse du modèle ne contient aucun code';
  files.length = 0;
} else if (options.taskMode && item.existingContent && files.length > 0 && sameAsExisting(files[0].content, item.existingContent)) {
  issues.push({ type: 'unchanged', message: 'Fichier renvoyé identique à existingContent : aucune modification appliquée' });
  generationError = 'no_op: le fichier renvoyé est identique à existingContent, rien n\'a été modifié';
  files.length = 0;
}
if (item.promptTruncations?.length) {
  issues.push({ type: 'prompt_truncated', message: 'Prompt tronqué : ' + item.promptTruncations.map(t => `${t.section} ${t.length}>${t.kept}`).join(', ') });
}
const result = {
  meta: {
    pattern, side, framework, fileCount: files.length, hasIssues: issues.length > 0, issues,
    model: generationMeta?.model ?? null, tokensUsed: generationMeta?.usage?.total_tokens ?? null,
    finishReason: generationMeta?.finishReason ?? null,
    promptTruncations: item.promptTruncations ?? [],
  },
  files,
  raw: rawOutput,
  summary: files.length > 0 ? `${files.length} fichier(s) généré(s)` : `Génération échouée — aucun fichier extrait`,
};
return [{ json: {
  ...item, response: result, generatedFiles: files, hasIssues: issues.length > 0, localCheckOk, localCheckReason,
  ...(generationError ? { error: generationError } : {}),
  qualityScore: files[0]?._qualityScore ?? null, // mode task : score de CE fichier
  globalQualityScore, // mode bulk : moyenne de tous les fichiers de ce run
  filesBelowThreshold, // fichiers <70 — à surveiller/escalader en priorité
} }];

// ═══════════════════════════════════════════════════════════
// FILE WRITER — Écrit les fichiers générés sur le disque
// Actif uniquement en mode task
// ═══════════════════════════════════════════════════════════
const fs   = require('fs');
const path = require('path');
const item = $input.first().json;

const { generatedFiles = [], projectBasePath, options = {} } = item;

// Passer en mode non-task sans écriture
if (!options.taskMode || item.step === 'contracts' || item.step === 'local-review' || item.step === 'thinking') {
  return [{ json: item }];
}

const writtenFiles = [];
const errors = [];

for (const file of generatedFiles) {
  if (!file.path) { continue; }
  try {
    const fullPath = path.join(projectBasePath, file.path);
    fs.mkdirSync(path.dirname(fullPath), { recursive: true });
    // Toujours une ligne vide finale (2026-10-02) : l'extraction du bloc de code la retirait, et tous les fichiers
    // écrits ce jour-là échouaient à eol-last (eslint) / Layout/TrailingEmptyLines (rubocop).
    const content = file.content.endsWith('\n') ? file.content : file.content + '\n';
    fs.writeFileSync(fullPath, content, 'utf8');
    writtenFiles.push(file.path);
    console.log(`[FILE WRITER] Écrit : ${fullPath}`);
  } catch(err) {
    errors.push({ path: file.path, error: err.message });
    console.error(`[FILE WRITER] Erreur : ${file.path} — ${err.message}`);
  }
}

return [{ json: { ...item, writtenFiles, writeErrors: errors, filesWritten: writtenFiles.length } }];

