const DOCKER_BRIDGE_TOKEN = require('fs').readFileSync('/run/secrets/docker-bridge-token', 'utf8').trim();
// ═══════════════════════════════════════════════════════════
// 07x · Test Runner — appelle docker-bridge via http natif (fetch
// n'est pas disponible dans le contexte des nœuds Code de n8n).
// ═══════════════════════════════════════════════════════════
const http = require('http');
const item = $input.first().json.body ?? $input.first().json;

const container = item.testContainer;
const testPath  = item.testPath || '';

if (!container) {
  return [{ json: { error: 'testContainer manquant dans la requête', passed: 0, failed: 0, total: 0, failures: [] } }];
}

const args = ['npx', 'vitest', 'run', '--reporter=json', '--coverage'];
if (testPath) { args.push(testPath); }

function httpPostJson(hostname, port, path, bodyObj) {
  return new Promise((resolve, reject) => {
    const bodyStr = JSON.stringify(bodyObj);
    const req = http.request({
      hostname,
      port,
      path,
      method: 'POST',
      headers: { 'Authorization': 'Bearer ' + DOCKER_BRIDGE_TOKEN,
        'Content-Type':   'application/json',
        'Content-Length': Buffer.byteLength(bodyStr),
      },
      timeout: 5 * 60 * 1000,
    }, (res) => {
      let data = '';
      res.on('data', chunk => { data += chunk; });
      res.on('end', () => {
        try { resolve(JSON.parse(data)); }
        catch (e) { reject(new Error(`Réponse non-JSON de docker-bridge (HTTP ${res.statusCode}) : ${data.substring(0, 300)}`)); }
      });
    });
    req.on('timeout', () => { req.destroy(new Error('Timeout docker-bridge')); });
    req.on('error', reject);
    req.write(bodyStr);
    req.end();
  });
}

let bridgeResponse;
try {
  bridgeResponse = await httpPostJson('docker-bridge', 3001, '/exec', { container, args });
} catch (e) {
  return [{ json: { error: `docker-bridge injoignable : ${e.message}`, passed: 0, failed: 0, total: 0, failures: [] } }];
}

if (bridgeResponse.error) {
  return [{ json: { error: bridgeResponse.error, passed: 0, failed: 0, total: 0, failures: [] } }];
}

const stdout = bridgeResponse.stdout || '';
let parsed = null;
const jsonMatch = stdout.match(/\{[\s\S]*\}/);
if (jsonMatch) {
  try { parsed = JSON.parse(jsonMatch[0]); } catch (e) {}
}

if (!parsed) {
  return [{ json: {
    error: 'Sortie Vitest non parsable — vérifier le format du --reporter=json de cette version',
    raw: (stdout + (bridgeResponse.stderr || '')).substring(0, 3000),
    passed: 0, failed: 0, total: 0, failures: [],
  } }];
}

const failures = [];
for (const suite of parsed.testResults ?? []) {
  for (const assertion of suite.assertionResults ?? []) {
    if (assertion.status === 'failed') {
      failures.push({
        file:    suite.name,
        test:    assertion.fullName ?? assertion.title ?? '(nom inconnu)',
        message: (assertion.failureMessages ?? []).join('\n').substring(0, 1000),
      });
    }
  }
}

// ── Résumé de couverture — lecture de coverage/coverage-summary.json ──
// (généré par le reporter 'json-summary' configuré dans vitest.config.ts)
let coverage = null;
try {
  const catResponse = await httpPostJson('docker-bridge', 3001, '/exec', {
    container, args: ['cat', 'coverage/coverage-summary.json'],
  });
  if (catResponse.exitCode === 0 && catResponse.stdout) {
    const covParsed = JSON.parse(catResponse.stdout);
    const total = covParsed.total ?? {};
    coverage = {
      lines:      total.lines?.pct      ?? null,
      statements: total.statements?.pct ?? null,
      functions:  total.functions?.pct  ?? null,
      branches:   total.branches?.pct   ?? null,
    };
  }
} catch (e) {
  // Pas de couverture disponible — pas bloquant, on continue sans.
}

return [{ json: {
  passed: parsed.numPassedTests ?? 0,
  failed: parsed.numFailedTests ?? 0,
  total:  parsed.numTotalTests ?? 0,
  failures,
  coverage,
} }];

const DOCKER_BRIDGE_TOKEN = require('fs').readFileSync('/run/secrets/docker-bridge-token', 'utf8').trim();
// ═══════════════════════════════════════════════════════════
// 07y · Dependency Installer — vérifie PUIS installe les dépendances
// manquantes uniquement, en un seul exec docker-bridge.
// Check via require.resolve (rapide, gère le hoisting workspaces) PUIS,
// en cas d'échec, remontée de répertoires à la recherche d'un
// node_modules/<pkg>/package.json (couvre les paquets ESM-only sans
// condition "require" dans leur "exports" que require.resolve() rejette
// à tort même quand le paquet est bien installé).
//
// ⚠️ Le sed d'extraction du nom de paquet scoped utilisait un delimiteur
// '/' avec un '\/' echappe dans le pattern -- dans un template literal JS,
// '\/' est silencieusement reduit a '/' (ce n'est pas une sequence
// d'echappement JS reconnue), ce qui cassait le script sed transmis au
// conteneur ("unknown option to 's'") et rendait $n TOUJOURS vide, donc
// TOUT paquet etait signale "manquant" et reinstalle inutilement -- bug
// confirme en test sur @vueuse/core (deja present, reinstalle a chaque
// appel). Fix : delimiteur '#' pour le premier sed, qui ne necessite pas
// d'echapper les '/' du pattern.
// Sortie : alreadyInstalled[], newlyInstalled[], total.
// ════════════════════════════════════════════════════════
const http = require('http');
const item = $input.first().json.body ?? $input.first().json;

const container      = item.testContainer;
const packageManager = item.packageManager; // 'npm' | 'pnpm' | 'yarn' | 'composer' | 'gem'
const packages        = item.packages ?? [];

if (!container)       { return [{ json: { error: 'testContainer manquant', success: false } }]; }
if (!packages.length)  { return [{ json: { error: 'Aucun package à installer', success: false } }]; }

const installCommands = {
  npm:      (pkgs) => ['npm', 'install', ...pkgs],
  pnpm:     (pkgs) => ['pnpm', 'add', ...pkgs],
  yarn:     (pkgs) => ['yarn', 'add', ...pkgs],
  composer: (pkgs) => ['composer', 'require', ...pkgs],
  gem:      (pkgs) => ['bundle', 'add', ...pkgs],
};
if (!installCommands[packageManager]) {
  return [{ json: { error: `Gestionnaire de paquets inconnu : ${packageManager}`, success: false } }];
}

function buildCheckScript(manager) {
  if (manager === 'npm' || manager === 'pnpm' || manager === 'yarn') {
    return `
already=""; missing=""
has_node=0
command -v node >/dev/null 2>&1 && has_node=1
for p in "$@"; do
  n=$(printf '%s' "$p" | sed -E 's#^(@[^/]+/[^@]+).*#\\1#; t; s/@.*//')
  ok=1
  if [ "$has_node" = "1" ]; then
    if node -e "try{require.resolve(process.argv[1]);process.exit(0)}catch(e){process.exit(1)}" "$n" >/dev/null 2>&1; then ok=0; fi
  fi
  if [ "$ok" != "0" ]; then
    dir=$(pwd)
    while [ -n "$dir" ]; do
      if [ -f "$dir/node_modules/$n/package.json" ]; then ok=0; break; fi
      [ "$dir" = "/" ] && break
      dir=$(dirname "$dir")
    done
  fi
  if [ "$ok" = "0" ]; then already="$already|$p"; else missing="$missing|$p"; fi
done
echo "ALREADY_LIST:$already"
echo "MISSING_LIST:$missing"
`.trim();
  }
  if (manager === 'composer') {
    return `
already=""; missing=""
for p in "$@"; do
  n=$(printf '%s' "$p" | cut -d: -f1)
  if composer show "$n" >/dev/null 2>&1; then already="$already|$p"; else missing="$missing|$p"; fi
done
echo "ALREADY_LIST:$already"
echo "MISSING_LIST:$missing"
`.trim();
  }
  if (manager === 'gem') {
    return `
already=""; missing=""
for p in "$@"; do
  n=$(printf '%s' "$p" | cut -d: -f1 | cut -d' ' -f1)
  if bundle show "$n" >/dev/null 2>&1; then already="$already|$p"; else missing="$missing|$p"; fi
done
echo "ALREADY_LIST:$already"
echo "MISSING_LIST:$missing"
`.trim();
  }
  return null;
}

function httpPostJson(hostname, port, path, bodyObj) {
  return new Promise((resolve, reject) => {
    const bodyStr = JSON.stringify(bodyObj);
    const req = http.request({
      hostname, port, path, method: 'POST',
      headers: { 'Authorization': 'Bearer ' + DOCKER_BRIDGE_TOKEN, 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(bodyStr) },
      timeout: 5 * 60 * 1000,
    }, (res) => {
      let data = '';
      res.on('data', chunk => { data += chunk; });
      res.on('end', () => {
        try { resolve(JSON.parse(data)); }
        catch (e) { reject(new Error(`Réponse non-JSON de docker-bridge (HTTP ${res.statusCode}) : ${data.substring(0, 300)}`)); }
      });
    });
    req.on('timeout', () => { req.destroy(new Error('Timeout docker-bridge')); });
    req.on('error', reject);
    req.write(bodyStr);
    req.end();
  });
}

const checkScript = buildCheckScript(packageManager);
const checkArgs = ['sh', '-c', checkScript, 'sh', ...packages];

let checkResponse;
try {
  checkResponse = await httpPostJson('docker-bridge', 3001, '/exec', { container, args: checkArgs });
} catch (e) {
  return [{ json: { error: `docker-bridge injoignable (check) : ${e.message}`, success: false } }];
}
if (checkResponse.error) {
  return [{ json: { error: checkResponse.error, success: false } }];
}

const checkStdout = checkResponse.stdout || '';
const alreadyLine = checkStdout.match(/ALREADY_LIST:(.*)/);
const missingLine = checkStdout.match(/MISSING_LIST:(.*)/);
const alreadyInstalled = alreadyLine ? alreadyLine[1].split('|').filter(Boolean) : [];
const toInstall        = missingLine ? missingLine[1].split('|').filter(Boolean) : packages.slice();

if (toInstall.length === 0) {
  return [{ json: {
    success: true,
    exitCode: 0,
    alreadyInstalled,
    newlyInstalled: [],
    totalRequested: packages.length,
    stdout: '(rien à installer, tous les packages étaient déjà présents)',
    stderr: '',
  } }];
}

const installArgs = installCommands[packageManager](toInstall);
let installResponse;
try {
  installResponse = await httpPostJson('docker-bridge', 3001, '/exec', { container, args: installArgs });
} catch (e) {
  return [{ json: {
    error: `docker-bridge injoignable (install) : ${e.message}`,
    success: false,
    alreadyInstalled,
    newlyInstalled: [],
    totalRequested: packages.length,
  } }];
}
if (installResponse.error) {
  return [{ json: {
    error: installResponse.error,
    success: false,
    alreadyInstalled,
    newlyInstalled: [],
    totalRequested: packages.length,
  } }];
}

const installSuccess = installResponse.exitCode === 0;

return [{ json: {
  success:  installSuccess,
  exitCode: installResponse.exitCode,
  alreadyInstalled,
  newlyInstalled: installSuccess ? toInstall : [],
  totalRequested: packages.length,
  stdout: (installResponse.stdout || '').substring(0, 3000),
  stderr: (installResponse.stderr || '').substring(0, 3000),
} }];

