    : `⚠️ Aucune URL de base backend n'a été fournie — utilise \`useRuntimeConfig().backendBaseUrl\` ` +
      `(ou \`process.env.BACKEND_API_URL\` côté server) et ajoute UNE ligne dans "implementationSteps" ` +
      `rappelant que cette variable d'environnement doit être configurée avant déploiement.`;

  // ── Fiche d'intégration RÉELLE pour ce backend (chargée depuis disque
  // par 03e, voir reference-sheets/auth-backends/) — générique, pas limité
  // à un framework en particulier. Si aucune fiche n'existe pour ce couple
  // framework+provider, instruction générique de repli.
  let conventionsLines;
  if (backendAuthSheet) {
    const s = backendAuthSheet;
    const csrfLine = s.csrf?.required
      ? `\n  - CSRF : requête préalable \`${s.csrf.fetchEndpoint ?? '(voir doc)'}\` → cookie ` +
        `\`${s.csrf.cookieName ?? '?'}\`, à renvoyer dans l'en-tête \`${s.csrf.headerName ?? '?'}\` sur les requêtes suivantes.`
      : '';
    const epLines = Object.entries(s.endpoints ?? {}).map(([action, ep]) =>
      `  - ${action} : \`${ep.method} ${ep.path}\`${ep.bodyShape ? `, body \`${ep.bodyShape}\`` : ''}`
    ).join('\n');
    conventionsLines =
      `- Le backend utilise ${s.library ?? s.framework} (mécanisme de session : ${s.sessionMechanism ?? 'inconnu'}). ` +
      `Conventions connues (fiche de référence — ne PAS en inventer d'autres) :\n${epLines}${csrfLine}` +
      (s.notes ? `\n  - Note : ${s.notes}` : '') +
      `\n- La réponse du backend porte l'info de session (cookie \`Set-Cookie\` ou token selon sessionMechanism) — ` +
      `le endpoint Nuxt doit la LIRE sur la réponse \`$fetch\` et soit la retransmettre au navigateur ` +
      `(\`setCookie(event, ...)\`), soit la stocker dans \`setUserSession(event, { user, ... })\` pour la rejouer ` +
      `sur les appels backend suivants. Ne JAMAIS l'ignorer — sans elle, les appels suivants ne seront pas authentifiés.\n` +
      `- \`setUserSession\`/\`clearUserSession\` (nuxt-auth-utils) restent utilisés côté Nuxt pour PROTÉGER les ` +
      `pages/routes Nuxt elles-mêmes — mais l'identité/le mot de passe sont vérifiés par le backend, jamais recalculés côté Nuxt.`;
  } else {
    conventionsLines =
      `- Aucune fiche de référence connue pour ce backend (${backendContext?.framework ?? '?'}` +
      (item.backendAuthProvider ? ` / ${item.backendAuthProvider}` : '') +
      `) — décris dans CHAQUE fichier \`server/api/*\` concerné la route backend EXACTE qu'il appelle ` +
      `(méthode + chemin), pour que le proxy soit vérifiable sans deviner. Si une doc backend est disponible, ` +
      `elle peut être ajoutée comme fiche de référence via le mode "update-reference-sheet" pour les prochaines tâches.`;
  }

  sections.push(
    `## ⚠️ Architecture d'intégration — stack scindée (${frontendContext?.framework} ↔ ${backendContext?.framework})\n\n` +
    `Le backend (${backendContext?.framework}) est un service SÉPARÉ qui possède déjà sa propre base de ` +
    `données et sa propre logique métier — ce n'est PAS un Nuxt fullstack. RÈGLE ABSOLUE :\n\n` +
    `- N'écris JAMAIS d'accès base de données, d'ORM, ni de hashing de mot de passe directement dans un ` +
    `fichier \`server/api/*\` côté Nuxt. Le backend ${backendContext?.framework} est l'UNIQUE source de vérité ` +
    `pour les données et l'authentification.\n` +
    `- Chaque endpoint \`server/api/*\` côté Nuxt lié à cette tâche doit être un PROXY fin vers le backend : ` +
    `valide le body (zod), appelle le backend via \`$fetch\`, transmet la réponse/erreur, et RIEN d'autre. ` +
    `Zéro \`TODO\`, zéro commentaire \"remplacer par une vraie vérification en base de données\" — le vrai ` +
    `traitement existe déjà côté backend, ce fichier ne fait que le relayer.\n` +
    `- ${baseUrlLine}\n` +
    conventionsLines
  );
}
if (uiComponentReferences && uiComponentReferences.length > 0) {
  sections.push(
    `## Composants UI RÉELS (source: ${uiComponentReferences[0].source === 'mcp' ? 'API officielle via MCP' : 'fiche locale'}) — ne pas inventer de props/events/slots\n\n` +
    uiComponentReferences.map(c =>
      `### ${c.component} (${c.library}${c.version ? ' v' + c.version : ''})\n` +
      '```json\n' + JSON.stringify(c.api, null, 2).substring(0, 2000) + '\n```'
    ).join('\n\n') +
    `\n\n⚠️ Utilise UNIQUEMENT les props/events/slots listés ci-dessus pour ces composants. ` +
    `Si une prop dont tu as besoin n'apparaît pas dans cette liste, ne l'invente pas — utilise une ` +
    `alternative documentée ou signale-le dans "planValidationIssues" via la description du fichier.`
  );
}
if (libraryReferences && libraryReferences.length > 0) {
  sections.push(
    `## Fonctions RÉELLES des dépendances tierces déclarées (ne pas en inventer d'autres)\n\n` +
    libraryReferences.map(lib =>
      `### ${lib.package}\n` +
      lib.exports.map(e => `- \`${e.name}\` (${e.side}) — ${e.note}`).join('\n')
    ).join('\n\n') +
    `\n\n⚠️ N'utilise QUE ces fonctions pour ces libs — n'invente jamais un nom qui ` +
    `ressemble mais n'est pas dans cette liste. Si un fichier utilise une de ces ` +
    `fonctions, note-la dans son champ "externalApisUsed".`
  );
}
if (forbidden && forbidden.length > 0) {
  sections.push(`## Interdits\n\n${forbidden.map(f => `- ${f.name}`).join('\n')}`);
}
if (domainModel) {
  sections.push(
    `## Ressources déjà existantes ailleurs dans le projet (RÉFÉRENCE UNIQUEMENT)\n\n` +
    `⚠️ Cette section liste ce qui existe DÉJÀ dans le reste du projet, pour information ` +
    `SEULEMENT. La tâche en cours porte sur l'entité nommée dans le titre/objectif de ` +
    `l'analyse fonctionnelle ci-dessus — PAS forcément une de celles listées ici. Si le ` +
    `titre/objectif parle d'une entité DIFFÉRENTE (ex: "catégories" alors que cette liste ` +
    `mentionne "Article"), IGNORE complètement cette section et construis les fichiers ` +
    `pour la VRAIE entité de la tâche, jamais pour une entité mentionnée ici par erreur ` +
    `de confusion.\n\n${domainModel.substring(0, 2500)}`
  );
}
if (existingCapabilities && Object.keys(existingCapabilities).length > 0) {
  // Version STRUCTURÉE et DÉDUPLIQUÉE (mémoire projet, .blackstaff/memory.json)
  // — contrairement au domainModel ci-dessus (log chronologique brut), ceci
  // donne l'état ACTUEL par entité, sans répétition même après de nombreuses
  // tâches passées. Filtré par 03 Context Resolver aux entités pertinentes.
  const capLines = Object.entries(existingCapabilities).map(([entity, cap]) => {
    const filesByCat = Object.entries(cap.files || {})
      .map(([cat, paths]) => `  - ${cat}: ${paths.join(', ')}`)
      .join('\n');
    return `### ${entity}\n${filesByCat}`;
  });
  sections.push(
    `## Capacités déjà construites pour ces entités (état actuel, dédupliqué)\n\n` +
    `${capLines.join('\n\n')}\n\n` +
    `⚠️ Si la tâche concerne une entité listée ci-dessus, NE RÉGÉNÈRE AUCUN des ` +
    `fichiers déjà listés — cette tâche doit se limiter à AJOUTER ce qui manque ` +
    `(nouveau champ, nouvelle relation, nouveaux fichiers liés à la nouveauté) ` +
    `ou MODIFIER explicitement un fichier existant si la tâche le demande. Ne ` +
    `jamais dupliquer un CRUD déjà en place.`
  );
}

if (item.correctionNotes) {
  sections.push(
    `## ⚠️ Ceci est une NOUVELLE TENTATIVE — une review a rejeté ton plan précédent\n\n` +
    `Remarques du reviewer sur CE QUE TU AVAIS PRODUIT AVANT :\n${item.correctionNotes}\n\n` +
    `Corrige EXACTEMENT ces points, sans rien changer d'autre par ailleurs. En particulier :\n` +
    `- Si le reviewer ne conteste PAS le choix de pattern (builder/crud/aucun), GARDE le ` +
    `même choix — ne réévalue pas depuis zéro comme si c'était une nouvelle tâche.\n` +
    `- Ne réduis JAMAIS le nombre de fichiers pour "simplifier" si le reviewer a demandé ` +
    `d'en AJOUTER (pages, endpoints, schéma zod manquants) — ajoute ce qui manque, ne ` +
    `bascule pas vers une structure plus simple pour éviter le problème.\n` +
    `- Traite chaque point du reviewer un par un et vérifie ta réponse finale contre ` +
    `cette liste avant de la considérer terminée.`
  );
}

const userPrompt = sections.join('\n\n---\n\n');

// ── Nettoie le vieux "text"/"response" de LLM#1 AVANT de repartir vers ──
// LLM#2 — sinon Merge1 risque de le faire gagner sur la vraie sortie de
// LLM#2 (même champ "text" des deux côtés), et 04c parserait l'ANALYSE
// FONCTIONNELLE en croyant lire le plan technique (0 fichier résultant).
const forwardItem = { ...item };
delete forwardItem.text;
delete forwardItem.response;

return [{ json: { ...forwardItem, functionalAnalysis, systemPrompt, userPrompt, contextDebug } }];

// ═══════════════════════════════════════════════════════════
// 04c · Description Formatter — PAS D'APPEL LLM ICI, code pur.
// Transforme le plan technique JSON (04b) en markdown final, et
// VALIDE réellement en code. Défensif contre les déviations de
// schéma d'un petit modèle (patterns en objets au lieu de strings,
// fichiers imbriqués dans patterns, etc.)
// ═══════════════════════════════════════════════════════════
const item = $input.first().json;
const { functionalAnalysis, taskTemplates, contextDebug } = item;
const knownExternalSymbols = item.knownExternalSymbols ?? [];
const { splitStack, backendBaseUrl, frontendContext, backendContext } = item;

// ── Parsing JSON robuste — tolère les erreurs de syntaxe courantes des LLM ──
// (virgule traînante avant } ou ], la plus fréquente).
function tryParseJson(text) {
  if (!text) return null;
  try { return JSON.parse(text); } catch (e) {}
  const m = text.match(/\{[\s\S]*\}/);
  if (!m) return null;
  const sanitized = m[0].replace(/,(\s*[}\]])/g, '$1');
  try { return JSON.parse(sanitized); } catch (e) { return null; }
}

const raw = (typeof item.response === 'string' ? item.response : null) ?? item.text ?? '';
let plan = tryParseJson(raw);

if (!plan) {
  return [{ json: { ...item, generatedTitle: null, generatedDescription: null, planValidationIssues: ['Plan technique non parsable — sortie LLM invalide'], contextDebug } }];
}

// ── Normalisation défensive — récupère ce qui est exploitable même si ──
// le modèle a dévié du schéma exact (patterns en objets, fichiers imbriqués).
function normalizePatterns(rawPatterns) {
  if (!Array.isArray(rawPatterns)) return [];
  return rawPatterns.map(p => (typeof p === 'string' ? p : (p?.name ?? null))).filter(Boolean);
}

function normalizeFiles(plan) {
  let files = Array.isArray(plan.files) ? [...plan.files] : [];
  // Récupère aussi des fichiers égarés dans patterns[].files, au cas où
  if (Array.isArray(plan.patterns)) {
    for (const p of plan.patterns) {
      if (p && Array.isArray(p.files)) {
        for (const f of p.files) {
          if (typeof f === 'string') { files.push({ path: f, category: 'Autres', description: '', exports: [] }); }
          else if (f && f.path) { files.push(f); }
        }
      }
    }
  }
  return files.filter(f => f && f.path);
}

const patterns = normalizePatterns(plan.patterns);
const files = normalizeFiles(plan);

// ── Correction déterministe des noms français résiduels ─────────────────
// Petit dictionnaire des termes qui reviennent RÉELLEMENT en pratique (pas
// un dictionnaire complet — juste ce qu'on a observé récidiver), pour
// corriger automatiquement sans repasser par un appel LLM complet.
const FR_EN_DICT = {
  'recherche': 'search', 'recherches': 'searches',
  'critère': 'criteria', 'critères': 'criteria',
  'catégorie': 'category', 'catégories': 'categories',
  'utilisateur': 'user', 'utilisateurs': 'users',
  'article': 'article', 'articles': 'articles',
  'motcle': 'keyword', 'motclé': 'keyword', 'motcles': 'keywords', 'motclés': 'keywords',
  'avancée': 'advanced', 'avancé': 'advanced',
};

function translateFrenchTokens(str) {
  if (!str) return str;
  let result = str;
  for (const [fr, en] of Object.entries(FR_EN_DICT)) {
    // Insensible à la casse, préserve la casse du premier caractère du match
    const re = new RegExp(fr, 'gi');
    result = result.replace(re, (match) => {
      const isCapitalized = match[0] === match[0].toUpperCase();
      return isCapitalized ? en[0].toUpperCase() + en.slice(1) : en;
    });
  }
  return result;
}

const remainingAccentIssues = [];
for (const f of files) {
  if (!f.path) continue;
  const original = f.path;
  f.path = translateFrenchTokens(f.path);
  // Type/Date → string (zod ne sérialise pas Date nativement en JSON)
  if (f.description) {
    f.description = f.description.replace(/\bDate\b/g, 'string');
  }
  // Détecte les accents résiduels non couverts par le dictionnaire —
  // signalé comme blocage plutôt que corrigé à l'aveugle (mot inconnu).
  if (/[àâäéèêëïîôöùûüÿçœæ]/i.test(f.path)) {
    remainingAccentIssues.push(f.path);
  }
}

// ── Normalisation MÉCANIQUE des chemins — le modèle se trompe de façon ────
// répétée et systématique sur le préfixe app/ de Nuxt 4 (biais d'entraînement
// Nuxt 3 trop ancré, résiste aux instructions en contexte) — on corrige en
// code plutôt que de continuer à instruire un modèle qui n'obéit pas.
const stackConfig  = item.stack?.frontend ?? item.stack?.backend ?? {};
const nuxtVersion  = String(stackConfig.version ?? '');
const isNuxtV4     = (item.resolvedFramework === 'nuxt' || item.framework === 'nuxt') && nuxtVersion === '4';

if (isNuxtV4) {
  const APP_PREFIXED_DIRS = ['composables', 'pages', 'components', 'middleware', 'stores', 'plugins', 'layouts'];
  for (const f of files) {
    if (!f.path) continue;
    for (const dir of APP_PREFIXED_DIRS) {
      if (f.path.startsWith(dir + '/')) { f.path = 'app/' + f.path; break; }
    }
    // types/ → shared/types/ spécifiquement pour Nuxt 4 (accessible aussi
    // côté server/, cf. frameworks/nuxt/v4.md)
    if (f.path.startsWith('types/')) { f.path = 'shared/' + f.path; }
  }
}

// ── Validation programmatique réelle ────────────────────────
const issues = [];
if (files.length === 0) {
  issues.push('Aucun fichier dans le plan technique — sortie LLM probablement incomplète ou hors-schéma.');
}

// ── Détection de contradiction justification vs fichiers réels ──────────
// Le LLM écrit parfois "pas de CRUD" dans patternJustification puis génère
// quand même une structure CRUD (list/get/create/update/remove) — les deux
// parties de sa réponse sont générées de façon incohérente entre elles.
// Détectable en code, sans dépendre d'un nouveau tour de LLM.
const justificationRejectsCrud = /pas de crud|sans crud|composable réactif simple/i
  .test(plan.patternJustification || '');
const crudShapedSignatures = ['list(', 'get(id)', 'create(', 'update(', 'remove('];
const filesLookLikeCrud = files.some(f => {
  const d = (f.description || '').toLowerCase();
  return crudShapedSignatures.filter(sig => d.includes(sig.toLowerCase())).length >= 3;
});
if (justificationRejectsCrud && filesLookLikeCrud) {
  issues.push(
    'Contradiction interne : la justification écarte explicitement le CRUD ' +
    '("pas de CRUD"/"composable réactif simple") mais au moins un fichier expose ' +
    'des signatures list()/get()/create()/update()/remove() typiques d\'un CRUD ' +
    'complet — le plan se contredit lui-même, à corriger avant génération.'
  );
}

// ── Détection déterministe : un fichier appelle l'API (composable/page qui
// utilise $fetch/useFetch, ou dont la description contient des signatures
// list()/get()/create()/... typiques d'un appel réseau) mais AUCUN fichier
// server/api/* n'existe dans le plan pour la même ressource — un composable
// ne peut pas "juste marcher" sans le endpoint qu'il appelle. Symétrique du
// check "endpoint sans consommateur" qu'on avait déjà côté planValidation —
// ici c'est l'inverse : consommateur sans endpoint. Détectable en code,
// avant même la review Claude, sans dépendre d'un tour de LLM.
const hasServerApiFile = files.some(f => /server\/api\//i.test(f.path ?? ''));
const NETWORK_CALL_HINTS = /\$fetch|usefetch|list\(|get\(id\)|create\(|update\(|remove\(|delete\(/i;
const filesImplyingNetworkCalls = files.filter(f => {
  if (/server\/api\//i.test(f.path ?? '')) return false; // exclu : lui-même EST le endpoint
  return NETWORK_CALL_HINTS.test(f.description ?? '');
});
if (filesImplyingNetworkCalls.length > 0 && !hasServerApiFile) {
  issues.push(
    `Aucun fichier "server/api/*" dans le plan alors que ` +
    `${filesImplyingNetworkCalls.map(f => f.path).join(', ')} implique un appel réseau ` +
    `($fetch/useFetch ou signature list/get/create/update/remove) — un composable ou une ` +
    `page ne peut pas fonctionner sans le endpoint serveur qu'il appelle. Ajoute le(s) ` +
    `fichier(s) server/api/*.{get,post,patch,delete}.ts manquant(s), ou retire l'appel réseau ` +
    `si la donnée doit être statique/locale.`
  );
}

// ── Détection déterministe : auth choisi sans aucune trace dans la VRAIE ──
// instruction utilisateur (spec brut, pas functionalAnalysis qui peut déjà
// être corrompue par une hallucination de 04a). "auth" est déclaré au niveau
// du PROJET (toujours disponible) — ça ne veut pas dire que CETTE tâche en
// a besoin. Bloque avant même la review Claude, sans dépendre d'un LLM.
// ── Détection déterministe : entité(s) du plan absente(s) de la VRAIE ──
// instruction utilisateur (spec brut) — signal quasi certain que le plan a
// dérivé vers une entité sans rapport (ex: "Tag" recopié d'un exemple/d'une
// mémoire alors que la tâche parle de "favoris"). Complète (sans remplacer)
// le fix modèle : reste utile même si un modèle plus faible est utilisé un
// jour pour économiser des ressources.
let criticalMismatch = false;
const planEntities = Array.isArray(plan.entities) ? plan.entities : [];
if (planEntities.length > 0) {
  const rawSpecLower = (item.spec ?? '').toLowerCase();
  const noEntityMatches = planEntities.every(e => {
    const eLower = String(e).toLowerCase();
    return eLower.length < 3 || !rawSpecLower.includes(eLower.replace(/s$/, ''));
  });
  if (noEntityMatches) {
    criticalMismatch = true;
    issues.push(
      `Aucune des entités du plan (${planEntities.join(', ')}) n'apparaît dans l'instruction ` +
      `originale de l'utilisateur — le plan a probablement dérivé vers une entité sans rapport ` +
      `avec la tâche demandée (référence apprise/mémoire recopiée par erreur). À reconstruire ` +
      `en repartant du sujet réel de la tâche.`
    );
  }
}

const chosenPatternsForCheck = Array.isArray(plan.patterns) ? plan.patterns : [];
if (chosenPatternsForCheck.includes('auth')) {
  const authKeywords = [
    'connexion', 'connecter', 'login', 'inscription', "s'inscrire", 'register',
    'déconnexion', 'déconnecter', 'logout', 'session', 'authentif', 'auth',
    'mot de passe', 'password', 'protég', 'sécuris', 'utilisateur connecté',
  ];
  const rawSpec = (item.spec ?? '').toLowerCase();
  const hasAuthKeyword = authKeywords.some(k => rawSpec.includes(k));
  if (!hasAuthKeyword) {
    issues.push(
      'Le pattern "auth" a été choisi mais AUCUN mot-clé lié à l\'authentification ' +
      '(connexion, session, inscription, protection...) n\'apparaît dans l\'instruction ' +
      'ORIGINALE de l\'utilisateur — "auth" est disponible car déclaré au niveau du ' +
      'projet, mais rien n\'indique que CETTE tâche précise en a besoin. Probable ' +
      'hallucination : à retirer sauf si la tâche le justifie réellement.'
    );
  }
}
if (splitStack) {
  const localDbHints = /db\.|prisma|drizzle|typeorm|sequelize|mongoose|new pool\(|createconnection/i;
  const proxyHints = /\$fetch|fetch\(|backendbaseurl|proxy/i;
  const serverApiFiles = files.filter(f => /server\/api\//i.test(f.path ?? ''));
  for (const f of serverApiFiles) {
    const desc = (f.description ?? '').toLowerCase();
    if (localDbHints.test(desc) && !proxyHints.test(desc)) {
      issues.push(
        `"${f.path}" décrit un accès base de données local alors que la stack est scindée ` +
        `(frontend ${frontendContext?.framework ?? '?'} / backend ${backendContext?.framework ?? '?'}) — ` +
        `ce endpoint doit proxier vers le backend, pas toucher une DB directement.`
      );
    }
  }
  if (serverApiFiles.length > 0 && !backendBaseUrl) {
    issues.push(
      `Stack scindée détectée mais aucune "backendBaseUrl" fournie — les endpoints proxy générés ` +
      `utiliseront un runtime config à configurer manuellement (voir implementationSteps).`
    );
  }
}
for (const p of remainingAccentIssues) {
  issues.push(`"${p}" contient des caractères accentués non traduits automatiquement (hors dictionnaire) — renomme en anglais avant génération.`);
}

// ── Détection de références fantômes — version affinée ──────────────
// Deux corrections par rapport à la première version :
// 1. Une fonction listée juste après "exporte" dans la description d'UN
//    fichier est une auto-déclaration, pas une référence externe — on
//    l'extrait et on l'ignore pour CE fichier (le modèle remplit rarement
//    le champ séparé "exports", tout est écrit dans "description").
// 2. Un appel précédé d'un "." (ex: schema.safeParse(...)) est un appel de
//    MÉTHODE sur un objet importé, pas une fonction "exportée par un
//    fichier du projet" à vérifier — on l'ignore.
const allExports = new Set(files.flatMap(f => f.exports ?? []));

function extractSelfDeclaredExports(desc) {
  const m = desc.match(/exporte\s*:?\s*(.+)/i);
  if (!m) return new Set();
  const calls = [...m[1].matchAll(/\b(\p{L}[\p{L}\p{N}_]*)\(/gu)].map(c => c[1]);
  return new Set(calls);
}

// Ces catégories décrivent TOUJOURS leurs propres exports par construction
// (c'est ce que les gabarits leur demandent) — plus fiable que de deviner
// via un mot-clé ("exporte") que le modèle formule de façon inconsistante.
const SELF_DECLARING_CATEGORIES = ['composable', 'builder', 'store'];

for (const f of files) {
  const category = (f.category ?? '').toLowerCase();
  if (SELF_DECLARING_CATEGORIES.some(c => category.includes(c))) { continue; }

  const desc = f.description ?? '';
  const selfDeclared = extractSelfDeclaredExports(desc);
  // Ne cherche les appels QU'APRÈS avoir retiré la portion auto-déclarée,
  // pour ne pas re-signaler les mêmes noms qu'on vient d'exclure.
  const referencedCalls = [...desc.matchAll(/(\.)?\b(\p{L}[\p{L}\p{N}_]*)\(/gu)]
    .map(m => ({ name: m[2], isMethodCall: !!m[1] }));

  for (const { name: call, isMethodCall } of referencedCalls) {
    if (call.length < 3 || isMethodCall) continue; // méthode sur un objet — pas concerné
    const isOwnExport = (f.exports ?? []).includes(call) || selfDeclared.has(call);
    const isKnownExportElsewhere = allExports.has(call);
    const isCommonJsKeyword = ['string', 'number', 'boolean', 'Array', 'Promise', 'Object'].includes(call);
    // Globaux auto-importés par Nuxt/Nitro/Vue — jamais "exportés" par un
    // fichier du projet, ne jamais les signaler comme fantômes.
    const isFrameworkGlobal = [
      'createError', 'defineEventHandler', 'readBody', 'getUserSession', 'setUserSession',
      'clearUserSession', 'navigateTo', 'definePageMeta', 'useRuntimeConfig', 'useFetch',
      'ref', 'reactive', 'computed', 'watch', 'onMounted', 'defineProps', 'defineEmits',
      'defineStore', 'defineNuxtRouteMiddleware', 'useRouter', 'useRoute', 'useState',
      'fetch', '$fetch', 'useFetch', 'setCookie', 'getCookie', 'parseCookies',
      // + fiches de référence des dépendances tierces déclarées (03e), au lieu
      // d'une liste figée qui oublie tout ce qu'on n'a pas pensé à coder en dur.
      ...knownExternalSymbols,
    ].includes(call);
    if (!isOwnExport && !isKnownExportElsewhere && !isCommonJsKeyword && !isFrameworkGlobal) {
      issues.push(`"${f.path}" référence "${call}(...)" qui n'est déclaré comme export d'aucun fichier — référence potentiellement fantôme.`);
    }
  }
}

// Le check "pattern sans fichier" par sous-chaîne était trop peu fiable
// (faux positif sur "crud", faux négatif sur "auth" via "authorId") — retiré.
// Cette vérification reste couverte par la review Claude, plus fiable ici
// qu'une heuristique regex sur un nom de pattern abstrait.

const authComposables = files.filter(f => /composable/i.test(f.category ?? '') && /auth|session|garde|guard/i.test(f.description ?? ''));
const hasMiddleware = files.some(f => /middleware/i.test(f.path ?? ''));
if (authComposables.length > 0 && !hasMiddleware) {
  issues.push(`Logique de garde/session détectée dans un composable (${authComposables.map(f => f.path).join(', ')}) sans middleware dédié.`);
}

// ── Construction du markdown final ──────────────────────────
const title = (functionalAnalysis?.title && functionalAnalysis.title.trim())
  ? functionalAnalysis.title
  : (plan.title || 'Nouvelle tâche');

const lines = [];
lines.push(`TITRE: ${title}`, '');
lines.push('## Objectif', '');
lines.push((functionalAnalysis?.goal && functionalAnalysis.goal.trim()) ? functionalAnalysis.goal : '(non précisé)', '');

// Filet de sécurité : si le LLM a oublié patternJustification (surtout probable
// quand patterns est vide), on génère une phrase par défaut plutôt que de laisser
// la review Claude sans AUCUNE explication du choix d'architecture.
const effectiveJustification = plan.patternJustification
  || ((patterns.length === 0)
    ? `Aucun pattern GoF/CRUD retenu — objet ${functionalAnalysis?.objectLifecycle === 'ephemeral' ? 'éphémère' : ''} traité avec un composable réactif simple.`
    : null);

if (effectiveJustification) {
  lines.push(`_Choix d'architecture : ${effectiveJustification}_`, '');
}

lines.push('## Fichiers à générer', '');

// ── Ordre de génération déterministe — types/contrats/middleware/utils
// AVANT ce qui les consomme (composables, endpoints, pages/components).
// Évite qu'un reviewer (local ou Claude) flague à tort "middleware non
// trouvé" simplement parce qu'il n'a pas encore été écrit à ce stade.
const CATEGORY_PRIORITY = [
  'types', 'contracts', 'config', 'middleware', 'utils',
  'composable', 'composables', 'store', 'builder',
  'server api', 'server-api', 'api', 'endpoints',
  'components', 'component', 'pages', 'page',
];
function categoryRank(cat) {
  const idx = CATEGORY_PRIORITY.indexOf((cat || 'Autres').toLowerCase());
  return idx === -1 ? CATEGORY_PRIORITY.length : idx;
}
files.sort((a, b) => categoryRank(a.category) - categoryRank(b.category));

// Transformation PURE, déterministe — jamais laissée au LLM.
// server/api/articles/index.get.ts   -> GET  /api/articles
// server/api/articles/[id].get.ts    -> GET  /api/articles/:id
// server/api/articles/index.post.ts  -> POST /api/articles
function filePathToApiUrl(filePath) {
  if (!filePath) return null;
  const m = filePath.match(/server\/api\/(.+)\.(get|post|put|delete|patch)\.(ts|js)$/i);
  if (!m) return null;
  let route = m[1].replace(/\/index$/, '');
  if (route === 'index') route = '';
  route = route.replace(/\[([^\]]+)\]/g, ':$1'); // [id] -> :id (segment dynamique Nitro)
  const url = ('/api/' + route).replace(/\/+$/, '') || '/api';
  return { method: m[2].toUpperCase(), url };
}

// ── Table de routage API — calculée une fois, ne JAMAIS laisser le LLM
// reconstruire l'URL depuis un chemin de fichier serveur (source du bug
// classique : $fetch('/server/api/articles/index.get.ts') au lieu de
// $fetch('/api/articles')).
const apiRoutes = files
  .map(f => ({ path: f.path, route: filePathToApiUrl(f.path) }))
  .filter(f => f.route);


const categories = [...new Set(files.map(f => f.category || 'Autres'))]
  .sort((a, b) => categoryRank(a) - categoryRank(b));
for (const cat of categories) {
  lines.push(`### ${cat}`, '');
  for (const f of files.filter(f => (f.category || 'Autres') === cat)) {
    const apis = (f.externalApisUsed ?? []).length ? ` [utilise: ${f.externalApisUsed.join(', ')}]` : '';
    lines.push(`- ${f.path} (${f.description ?? ''})${apis}`);
  }
  lines.push('');
}

if (apiRoutes.length > 0) {
  lines.push('## Table de routage API (calculée — ne jamais réinventer une URL depuis un chemin de fichier)', '');
  for (const r of apiRoutes) {
    lines.push(`- ${r.path} -> ${r.route.method} ${r.route.url}`);
  }
  lines.push('', '⚠️ Toute page qui consomme une de ces routes doit utiliser EXACTEMENT l\'URL ci-dessus ' +
    '(ex: useFetch(\'' + (apiRoutes[0]?.route.url ?? '/api/...') + '\')) — jamais le chemin du fichier serveur.', '');
}

if ((plan.entities ?? []).length > 0) {
  lines.push('## Entités principales', '', plan.entities.join(', '), '');
}

const deps = item.dependencies ?? { npm: [], composer: [], gem: [] };
const depTotal = (deps.npm?.length ?? 0) + (deps.composer?.length ?? 0) + (deps.gem?.length ?? 0);
if (depTotal > 0) {
  lines.push('## Dépendances déclarées', '');
  if (deps.npm?.length)      { lines.push(`- npm : ${deps.npm.join(', ')}`); }
  if (deps.composer?.length) { lines.push(`- composer : ${deps.composer.join(', ')}`); }
  if (deps.gem?.length)      { lines.push(`- gem : ${deps.gem.join(', ')}`); }
  lines.push('');
}

const generatedDescription = lines.join('\n').trim();

const taskTemplatesContent = (taskTemplates ?? [])
  .map(t => `### Pattern "${t.patternKey}"\n\n${t.template}`)
  .join('\n\n---\n\n');

// ── Contrats dérivés — réutilise les auto-déclarations extraites pour ──
// donner à la review Claude (côté extension) de vrais exports croisés,
// au lieu de "(aucun)" alors que l'info existe déjà dans les descriptions.
const derivedContracts = files
  .map(f => ({ path: f.path, exports: [...extractSelfDeclaredExports(f.description ?? ''), ...(f.exports ?? [])] }))
  .filter(c => c.exports.length > 0);

// ── Patterns RÉELLEMENT choisis pour CETTE tâche (04b), distinct de
// patternsResolved qui reste la liste des patterns DISPONIBLES au niveau
// du projet. Sans ça, la review Claude reçoit la liste projet entière et
// reproche à tort l'absence de fichiers pour des patterns jamais choisis.
const chosenPatterns = Array.isArray(plan.patterns) ? plan.patterns : [];

// ── Résumé par fichier des APIs externes utilisées (déclarées par le LLM
// dans "externalApisUsed", complétées par une détection texte de secours
// si le champ est vide mais qu'un symbole connu apparaît dans la description) ──
const externalApiUsage = files.map(f => {
  const declared = Array.isArray(f.externalApisUsed) ? f.externalApisUsed : [];
  const desc = f.description ?? '';
  const detected = knownExternalSymbols.filter(sym => desc.includes(sym) && !declared.includes(sym));
  const used = [...new Set([...declared, ...detected])];
  return used.length ? { path: f.path, externalApisUsed: used } : null;
}).filter(Boolean);

return [{ json: {
  ...item,
  generatedTitle: title,
  generatedDescription,
  taskTemplatesContent,
  planValidationIssues: issues,
  derivedContracts,
  externalApiUsage,
  apiRoutes,
  chosenPatterns,
  patternJustification: effectiveJustification,
  criticalMismatch,
  contextDebug,
} }];

// ═══════════════════════════════════════════════════════════
// 04e · Decompose Formatter — parse la réponse JSON du LLM et
// la met en forme pour l'extension (renderTasks() côté webview
// attend { tasks: [{ title, instruction, status? }, ...] }).
// PAS d'appel LLM ici, code pur — même philosophie que 04c.
// ═══════════════════════════════════════════════════════════
const item = $input.first().json;
const raw = (typeof item.text === 'string' ? item.text : null)
  ?? (typeof item.response === 'string' ? item.response : null)
  ?? '';

function tryParseJson(text) {
  if (!text) return null;
  let cleaned = text.trim();
  const fenceMatch = cleaned.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
  if (fenceMatch) { cleaned = fenceMatch[1]; }
  try { return JSON.parse(cleaned); }
  catch (e) {
    // Tolère une virgule traînante avant ] ou }
    try { return JSON.parse(cleaned.replace(/,(\s*[\]}])/g, '$1')); }
    catch (e2) { return null; }
  }
}

const parsed = tryParseJson(raw);
let tasks = [];

if (Array.isArray(parsed)) {
  tasks = parsed
    .filter(t => t && typeof t.title === 'string' && typeof t.instruction === 'string')
    .map(t => ({ title: t.title.trim(), instruction: t.instruction.trim(), status: 'pending' }));
}

const issues = [];
if (tasks.length === 0) {
  issues.push('Aucune tâche exploitable extraite de la réponse LLM — sortie invalide ou hors-schéma.');
}

return [{ json: { tasks, decomposeIssues: issues } }];

// ═══════════════════════════════════════════════════════════
// 04f · Test Generator — reçoit UN SEUL fichier réellement généré
// (grâce à 04f0/04f1 en amont) et construit le prompt pour CE
// fichier uniquement. Un item = un fichier = un appel LLM séparé.
// Prompt spécialisé pour les .vue (mount/@vue/test-utils) — un test
// de composant n'a pas la même forme qu'un test de fonction pure.
// ═══════════════════════════════════════════════════════════
const item = $json;
const { file, spec, framework } = item;

const isVueComponent = file.path.endsWith('.vue');

const commonRules = `Format de sortie STRICT — un seul bloc, pour CE fichier uniquement :
\`\`\`typescript
# tests/unit/xxx.test.ts
<contenu complet du fichier de test>
\`\`\`

Ne génère rien d'autre que ce bloc — pas d'introduction, pas d'explication,
pas de texte avant ou après.

Règles :
- Base-toi UNIQUEMENT sur les signatures/exports/props/emits RÉELS du fichier
  fourni ci-dessous — n'invente AUCUNE fonction/prop/event qui n'existe pas
  dans le code montré.
- Utilise Vitest (describe/it/expect) sauf si le framework du projet (${framework ?? 'inconnu'})
  indique un autre outil de test.`;

const systemPrompt = isVueComponent
  ? `Tu es un développeur qui écrit des tests de COMPOSANT Vue avec Vitest +
@vue/test-utils, pour du code DÉJÀ ÉCRIT — pas un plan à deviner, le vrai
composant, avec ses vraies props/emits/éléments.

${commonRules}
- Utilise \`mount()\` de '@vue/test-utils' — jamais de rendu manuel du template.
- Teste au minimum : que le composant se monte sans erreur (cas nominal), et
  UN comportement utilisateur réel visible dans le <script> (ex: un submit de
  formulaire qui émet un event, un champ qui met à jour v-model, une erreur de
  validation affichée). Ne teste PAS le contenu statique du template (texte,
  classes CSS) sauf s'il conditionne un comportement.
- Si le composant appelle une API (\`$fetch\`, \`useFetch\`, un composable
  d'auth) mock-la avec \`vi.fn()\` / \`vi.mock()\` — ne fais jamais un vrai
  appel réseau dans le test.
- N'invente AUCUN prop/emit qui n'apparaît pas dans \`defineProps\`/\`defineEmits\`
  du fichier fourni.`.trim()
  : `Tu es un développeur qui écrit des tests unitaires pour du code
DÉJÀ ÉCRIT — pas un plan à deviner, le vrai code, avec ses vraies signatures.

${commonRules}
- Teste au minimum : le cas nominal (succès), et un cas d'erreur/validation si le
  fichier en contient (ex: un schéma zod avec des contraintes min/max, une session absente).
- Ne teste pas l'UI en profondeur si aucun outil de test de composants n'est
  clairement configuré — privilégie la logique pure exposée par ce fichier.`.trim();

const userPrompt = `## Contexte de la tâche\n\n${spec}\n\n` +
  `## Fichier à tester : ${file.path}\n\n` +
  '```' + (isVueComponent ? 'vue' : 'typescript') + '\n' + file.content + '\n```';

return { json: { ...item, systemPrompt, userPrompt } };

// ═══════════════════════════════════════════════════════════
// 04g · Test Formatter — parse la réponse markdown-fence du LLM pour
// UN SEUL fichier de test (1 item = 1 fichier source = 1 fichier de
// test attendu). Même logique de parsing que la version précédente,
// adaptée à un seul bloc au lieu d'un scan multi-blocs.
// ═══════════════════════════════════════════════════════════
const item = $json;
const raw = (typeof item.text === 'string' ? item.text : null)
  ?? (typeof item.response === 'string' ? item.response : null)
  ?? '';

function parseFirstTestFile(output) {
  if (!output) return null;
  const blockRegex = /```(\w+)\n([\s\S]*?)```/;
  let match = blockRegex.exec(output);
  let content;
  if (match) {
    content = match[2].trim();
  } else {
    // Fallback : bloc ouvert jamais fermé (troncature num_predict)
    const openMatch = output.match(/```(\w+)\n([\s\S]*)/);
    if (!openMatch) return null;
    content = openMatch[2].replace(/`{1,3}[^\n`]{0,30}$/, '').trim();
  }
  const firstLine = content.split('\n')[0];
  const pathMatch = firstLine.match(/^(?:#|\/\/|<!--)\s*([^\s>]+\.\w+)/);
  const filePath = pathMatch ? pathMatch[1] : `tests/unit/${(item.file?.path ?? 'unknown').replace(/[\\/]/g, '_')}.test.ts`;
  const fileContent = pathMatch ? content.split('\n').slice(1).join('\n').trim() : content;
  if (!fileContent || fileContent.length <= 20) return null;
  return { path: filePath, content: fileContent, sourcePath: item.file?.path ?? null };
}

const testFile = parseFirstTestFile(raw);

return {
  json: {
    ...item,
    testFile,
    testGenerationIssue: testFile ? null : `Échec de génération pour ${item.file?.path ?? 'fichier inconnu'} (sortie vide ou invalide).`
  }
};

// ═══════════════════════════════════════════════════════════
// 04f0 · Split Testable Files — explose generatedFiles en N items
// (1 fichier testable = 1 item), pour que 04f/LLM#3/04g tournent une
// fois par fichier au lieu d'un seul gros prompt qui tronque ou
// n'en couvre qu'un sur cinq. Le filtrage "testable ou pas" est fait
// ici, en JS déterministe, plutôt que délégué au LLM dans le prompt.
//
// ⚠️ item.dependencies est un OBJET { npm: [...], composer: [...],
// gem: [...] } (voir 04c), PAS un tableau à plat — aplatir avant tout
// usage. Tout le filtrage est aussi enveloppé en try/catch : une
// erreur sur UN fichier ne doit jamais faire échouer tout le lot
// silencieusement (elle est alors traitée comme "non testable" avec
// la raison consignée, plutôt que de crasher tout le node).
// ═══════════════════════════════════════════════════════════
const item = $input.first().json;
const { generatedFiles, spec, framework } = item;

function flattenDependencies(deps) {
  if (!deps) return [];
  if (Array.isArray(deps)) return deps.map(String); // tableau déjà à plat (compat)
  return [
    ...(deps.npm ?? []),
    ...(deps.composer ?? []),
    ...(deps.gem ?? []),
  ].map(String);
}
const dependencies = flattenDependencies(item.dependencies ?? item.npmDependencies);
const depsText = dependencies.join(' ').toLowerCase();

const NON_TESTABLE_EXT = /\.d\.ts$/;
const TYPE_ONLY_PATH = /(^|\/)types?\//i;

function looksTestable(f) {
  if (!f?.path || !f?.content) return false;
  if (NON_TESTABLE_EXT.test(f.path)) return false;

  const body = f.content;
  const hasFunctionLogic = /\bfunction\b|=>|\bclass\b|export\s+(async\s+)?function|defineEventHandler|defineNuxtRouteMiddleware/.test(body);

  // Fichier de types (dossier /types/) sans aucune logique exécutable
  if (TYPE_ONLY_PATH.test(f.path) && !hasFunctionLogic) return false;

  // Schéma zod "nu" sans fonction autour (juste des exports de schémas/types)
  const onlyZodSchema = /z\.object\(/.test(body) && !hasFunctionLogic;
  if (onlyZodSchema) return false;

  // Composants .vue : seulement si un outil de test de composants est déclaré
  if (f.path.endsWith('.vue')) {
    const hasComponentTestTool = /@vue\/test-utils|@testing-library\/vue|cypress|playwright/.test(depsText);
    if (!hasComponentTestTool) return false;
  }

  return true;
}

function complexityScore(f) {
  const body = f.content;
  let score = 0;
  score += (body.match(/\bif\s*\(/g) ?? []).length;
  score += (body.match(/\.parse(Async)?\(/g) ?? []).length * 2;
  score += (body.match(/\bcatch\b/g) ?? []).length;
  if (f.path.endsWith('.vue')) score += (body.match(/@click|@submit|v-model/g) ?? []).length;
  return score;
}

const testable = [];
const skipped = [];
for (const f of (generatedFiles ?? [])) {
  try {
    if (looksTestable(f)) { testable.push(f); }
    else { skipped.push({ path: f?.path ?? '(chemin inconnu)', reason: 'non testable (type/schéma pur, ou outil de test composant absent)' }); }
  } catch (e) {
    // Ne fait JAMAIS échouer tout le node pour un seul fichier problématique —
    // ce fichier est juste exclu, avec la raison consignée pour debug.
    skipped.push({ path: f?.path ?? '(chemin inconnu)', reason: `erreur pendant le filtrage : ${e.message}` });
  }
}
testable.sort((a, b) => complexityScore(b) - complexityScore(a));

if (testable.length === 0) {
  return [{
    json: {
      ...item,
      file: null,
      _splitEmpty: true,
      _emptyReason: skipped.length
        ? `Aucun fichier testable — ${skipped.length} fichier(s) exclu(s) : ${skipped.map(s => `${s.path} (${s.reason})`).join('; ')}`
        : 'Aucun fichier généré à tester.',
    }
  }];
}

return testable.map(file => ({
  json: {
    file,
    spec,
    framework,
    dependencies,
    _totalTestableFiles: testable.length,
    _skippedFiles: skipped,
  }
}));

// ═══════════════════════════════════════════════════════════
// 04g2 · Test Aggregator — recombine les N items (1 par fichier de
// test généré ET exécuté par 04g1, ou l'unique item "vide" venant de
// 04f1=false) en 1 seul item attendu par 08 · Respond to Webhook :
//   - testFiles            : contenu des fichiers de test générés
//   - testGenerationIssues : échecs de génération/parsing
//   - testExecutionResults : résultat vitest RÉEL par fichier (si exécuté)
//   - testsPassed/testsFailed/testsTotal : totaux agrégés tous fichiers confondus
// ═══════════════════════════════════════════════════════════
const items = $input.all();
const testFiles = [];
const issues = [];
const executionResults = [];
let testsPassed = 0, testsFailed = 0, testsTotal = 0;
let anyExecuted = false;

for (const it of items) {
  const j = it.json;
  if (j._splitEmpty) {
    if (j._emptyReason) issues.push(j._emptyReason);
    continue;
  }
  if (j.testFile) testFiles.push(j.testFile);
  if (j.testGenerationIssue) issues.push(j.testGenerationIssue);

  if (j.testFileWritten) {
    const entry = { path: j.testFile?.path ?? null, sourcePath: j.file?.path ?? null };
    if (j.testRunSkipped) {
      entry.executed = false;
      entry.reason = j.testRunSkipReason ?? null;
    } else if (j.testRunOk) {
      anyExecuted = true;
      entry.executed = true;
      entry.passed = j.testRunPassed ?? 0;
      entry.failed = j.testRunFailed ?? 0;
      entry.total = j.testRunTotal ?? 0;
      entry.failures = j.testRunFailures ?? [];
      testsPassed += entry.passed;
      testsFailed += entry.failed;
      testsTotal  += entry.total;
    } else {
      entry.executed = false;
      entry.error = j.testRunError ?? 'Erreur inconnue';
    }
    executionResults.push(entry);
  }
}

if (testFiles.length === 0 && issues.length === 0) {
  issues.push('Aucun fichier de test généré (soit rien de testable, soit sortie vide/invalide).');
}

const base = { ...(items[0]?.json ?? {}) };
delete base.file;
delete base.testFile;
delete base.testGenerationIssue;
delete base._splitEmpty;
delete base._emptyReason;
delete base._totalTestableFiles;
delete base.systemPrompt;
delete base.userPrompt;
delete base.text;
delete base.response;
delete base.testFileWritten;
delete base.testRunSkipped;
delete base.testRunSkipReason;
delete base.testRunOk;
delete base.testRunError;
delete base.testRunRaw;
delete base.testRunPassed;
delete base.testRunFailed;
delete base.testRunTotal;
delete base.testRunFailures;

return [{ json: {
  ...base,
  testFiles,
  testGenerationIssues: issues,
  testExecutionResults: executionResults,
  testsExecuted: anyExecuted,
  testsPassed,
  testsFailed,
  testsTotal,
} }];

// ═══════════════════════════════════════════════════════════
// 03e · Library Reference Sheets — attache une fiche de référence pour
// chaque dépendance tierce déclarée (libraries/) ET une fiche d'intégration
// backend (auth-backends/) si la tâche déclare backendAuthProvider.
// Objectif : que 04b (plan) et 04c (validation) connaissent les VRAIES
// fonctions/routes d'une lib au lieu de deviner/halluciner.
//
// Les fiches vivent sur DISQUE (reference-sheets/) et sont mises à jour
// via le mode "update-reference-sheet" (02r→...→07r), jamais éditées ici.
// Un petit fallback embarqué couvre nuxt-auth-utils au cas où aucune
// fiche n'a encore été placée sur disque pour un projet neuf.
// ═══════════════════════════════════════════════════════════
const fs   = require('fs');
const path = require('path');
const item = $input.first().json;

const BLACKSTAFF_ROOT = `/home/node/projets/blackstaff/`;
const SHEETS_ROOT = path.join(BLACKSTAFF_ROOT, 'reference-sheets');
const LIBRARIES_DIR = path.join(SHEETS_ROOT, 'libraries');
const AUTH_BACKENDS_DIR = path.join(SHEETS_ROOT, 'auth-backends');
const UI_COMPONENTS_DIR = path.join(SHEETS_ROOT, 'ui-components');

function readJson(p) {
  try { return fs.existsSync(p) ? JSON.parse(fs.readFileSync(p, 'utf8')) : null; }
  catch (e) { return null; }
}

// ── Même validateur minimal que 07r — défense en profondeur : une fiche
// corrompue (édition manuelle ratée, écriture partielle) ne doit jamais
// être injectée telle quelle dans un prompt de génération. ──
function validateSchema(data, schema, p = '') {
  const errors = [];
  function typeOf(v) { if (v === null) return 'null'; if (Array.isArray(v)) return 'array'; return typeof v; }
  function walk(value, sch, path) {
    if (sch.type) {
      const allowed = Array.isArray(sch.type) ? sch.type : [sch.type];
      const actual = typeOf(value);
      if (!allowed.includes(actual)) { errors.push(`${path || '(racine)'} : type attendu [${allowed.join('|')}], reçu "${actual}"`); return; }
    }
    if (sch.enum && !sch.enum.includes(value)) { errors.push(`${path} : valeur hors enum`); }
    if (sch.pattern && typeof value === 'string' && !new RegExp(sch.pattern).test(value)) { errors.push(`${path} : pattern invalide`); }
    if (sch.properties && value !== null && typeof value === 'object' && !Array.isArray(value)) {
      for (const req of sch.required ?? []) { if (!(req in value)) errors.push(`${path || '(racine)'} : champ requis "${req}" manquant`); }
      for (const [key, subSchema] of Object.entries(sch.properties)) { if (key in value) walk(value[key], subSchema, path ? `${path}.${key}` : key); }
    }
    if (sch.items && Array.isArray(value)) { value.forEach((item, i) => walk(item, sch.items, `${path}[${i}]`)); }
  }
  walk(data, schema, p);
  return errors;
}
const SCHEMAS_ROOT = path.join(`/home/node/projets/blackstaff/okf`, 'contracts');
const SCHEMA_FILES = { library: 'library.schema.json', 'auth-backend': 'auth-backend.schema.json', 'ui-component': 'ui-component.schema.json', 'http-api': 'http-api.schema.json' };
function loadSchema(sheetType) {
  try { return JSON.parse(fs.readFileSync(path.join(SCHEMAS_ROOT, SCHEMA_FILES[sheetType]), 'utf8')); }
  catch (e) { return null; }
}
// readJson devient readValidatedJson : refuse une fiche qui ne respecte pas
// son schéma plutôt que de la faire confiance silencieusement.
function readValidatedJson(p, sheetType) {
  const parsed = readJson(p);
  if (!parsed) return null;
  const schema = loadSchema(sheetType);
  if (!schema) return parsed; // pas de schéma trouvé -> on ne bloque pas, meilleur effort
  const errors = validateSchema(parsed, schema);
  if (errors.length > 0) {
    console.log(`[03e] Fiche ignorée (invalide contre ${sheetType}.schema.json) : ${p} — ${errors.join(' | ')}`);
    return null;
  }
  return parsed;
}


