  else if (parsed.exports.some(e => !e.name)) errors.push('Un export sans "name" a été trouvé.');
} else {
  if (!parsed.endpoints || typeof parsed.endpoints !== 'object') errors.push('"endpoints" manquant ou invalide.');
}

return [{ json: {
  ...loaderItem,
  extractedSheet: parsed,
  extractionErrors: errors,
  extractionOk: errors.length === 0,
} }];

