// 07r · Reference Sheet Writer — écrit la fiche extraite en ".pending.json"
// à CÔTÉ du fichier réel (jamais d'écrasement direct) — une fiche de
// référence alimente directement la génération de code et la détection
// de "référence fantôme", une erreur d'extraction s'y répercuterait
// silencieusement. Review humaine avant de renommer le .pending.json.
// ═══════════════════════════════════════════════════════════
const fs   = require('fs');
const path = require('path');
const item = $input.first().json;


// ── Validateur JSON Schema minimal, SANS dépendance externe (ajv non
// garanti présent dans l'environnement Node du node Code n8n) ──
function validateSchema(data, schema, p = '') {
  const errors = [];
  function typeOf(v) { if (v === null) return 'null'; if (Array.isArray(v)) return 'array'; return typeof v; }
  function walk(value, sch, path) {
    if (sch.type) {
      const allowed = Array.isArray(sch.type) ? sch.type : [sch.type];
      const actual = typeOf(value);
      if (!allowed.includes(actual)) { errors.push(`${path || '(racine)'} : type attendu [${allowed.join('|')}], reçu "${actual}"`); return; }
    }
    if (sch.enum && !sch.enum.includes(value)) { errors.push(`${path} : valeur ${JSON.stringify(value)} absente de l'enum [${sch.enum.map(v => JSON.stringify(v)).join(', ')}]`); }
    if (sch.pattern && typeof value === 'string' && !new RegExp(sch.pattern).test(value)) { errors.push(`${path} : "${value}" ne respecte pas le pattern ${sch.pattern}`); }
    if (sch.properties && value !== null && typeof value === 'object' && !Array.isArray(value)) {
      for (const req of sch.required ?? []) { if (!(req in value)) errors.push(`${path || '(racine)'} : champ requis "${req}" manquant`); }
      for (const [key, subSchema] of Object.entries(sch.properties)) { if (key in value) walk(value[key], subSchema, path ? `${path}.${key}` : key); }
      if (sch.additionalProperties === false) {
        for (const key of Object.keys(value)) { if (!(key in sch.properties)) errors.push(`${path} : champ non déclaré "${key}"`); }
      }
    }
    if (sch.items && Array.isArray(value)) { value.forEach((item, i) => walk(item, sch.items, `${path}[${i}]`)); }
  }
  walk(data, schema, p);
  return errors;
}

function loadSchemaFor(sheetType) {
  const SCHEMAS_ROOT = `/home/node/projets/blackstaff/okf/contracts`;
  const fileMap = { library: 'library.schema.json', 'auth-backend': 'auth-backend.schema.json', 'ui-component': 'ui-component.schema.json' };
  const fname = fileMap[sheetType];
  if (!fname) return null;
  try { return JSON.parse(fs.readFileSync(path.join(SCHEMAS_ROOT, fname), 'utf8')); }
  catch (e) { return null; } // schéma absent -> pas de validation stricte possible, on ne bloque pas pour ça
}

// ── Validation JSON Schema AVANT écriture — une fiche malformée ne doit
// jamais atteindre .pending.json, encore moins être promue en fiche
// active par un reviewer pressé qui ne recompare pas champ par champ. ──
const schema = loadSchemaFor(item.sheetType);
let schemaErrors = [];
if (item.extractionOk && schema) {
  schemaErrors = validateSchema(item.extractedSheet, schema);
  if (schemaErrors.length > 0) {
    return [{ json: { ...item, written: false, reason: `Fiche extraite invalide (schéma ${item.sheetType}) : ` + schemaErrors.join(' | ') } }];
  }
}

if (!item.extractionOk) {
  return [{ json: { ...item, written: false, reason: 'Extraction invalide, rien écrit : ' + item.extractionErrors.join('; ') } }];
}

function diffExports(oldSheet, newSheet) {
  const oldNames = new Set((oldSheet?.exports ?? []).map(e => e.name));
  const newNames = new Set((newSheet?.exports ?? []).map(e => e.name));
  return {
    added:   [...newNames].filter(n => !oldNames.has(n)),
    removed: [...oldNames].filter(n => !newNames.has(n)),
  };
}
function diffUiComponentApi(oldSheet, newSheet) {
  const before = JSON.stringify(oldSheet?.api ?? null);
  const after  = JSON.stringify(newSheet?.api ?? null);
  return { apiChanged: before !== after, version: newSheet?.version ?? null };
}
function diffEndpoints(oldSheet, newSheet) {
  const keys = new Set([...Object.keys(oldSheet?.endpoints ?? {}), ...Object.keys(newSheet?.endpoints ?? {})]);
  const changed = [];
  for (const k of keys) {
    const before = JSON.stringify(oldSheet?.endpoints?.[k] ?? null);
    const after  = JSON.stringify(newSheet?.endpoints?.[k] ?? null);
    if (before !== after) { changed.push({ endpoint: k, before: oldSheet?.endpoints?.[k] ?? null, after: newSheet?.endpoints?.[k] ?? null }); }
  }
  return changed;
}

let diff;
if (item.sheetType === 'library') { diff = diffExports(item.existingSheet, item.extractedSheet); }
else if (item.sheetType === 'ui-component') { diff = diffUiComponentApi(item.existingSheet, item.extractedSheet); }
else { diff = { changedEndpoints: diffEndpoints(item.existingSheet, item.extractedSheet) }; }

try {
  fs.mkdirSync(path.dirname(item.pendingPath), { recursive: true });
  fs.writeFileSync(item.pendingPath, JSON.stringify(item.extractedSheet, null, 2), 'utf8');
  return [{ json: { ...item, written: true, diff } }];
} catch (e) {
  return [{ json: { ...item, written: false, reason: e.message } }];
}

