// sur disque (même technique que 07b · File Writer) puis l'exécute
// SEUL via vitest (même technique http natif que 07x · Test Runner),
// un fichier à la fois, immédiatement après sa génération. Ainsi
// chaque test généré a un résultat pass/fail RÉEL avant l'agrégation
// finale, pas seulement une review heuristique statique.
//
// Nécessite item.projectBasePath (toujours présent, posé en 02t) ET
// item.testContainer (optionnel — à fournir par l'appelant sur la
// requête "generate-tests" pour activer l'exécution ; sans lui, le
// test est écrit sur disque mais son exécution est marquée "ignorée").
// ═══════════════════════════════════════════════════════════
const fs   = require('fs');
const path = require('path');
const http = require('http');
const item = $json;

if (!item.testFile) {
  // Rien à écrire/exécuter pour cet item (cas "aucun fichier testable"
  // venu de 04f1=false, ou testFile null après un échec de parsing).
  return { json: item };
}

if (!item.projectBasePath) {
  return { json: { ...item, testRunSkipped: true, testRunSkipReason: 'projectBasePath manquant' } };
}

// ── Écriture sur disque (chemin partagé avec le conteneur de test) ──
const fullPath = path.join(item.projectBasePath, item.testFile.path);
try {
  fs.mkdirSync(path.dirname(fullPath), { recursive: true });
  fs.writeFileSync(fullPath, item.testFile.content, 'utf8');
} catch (e) {
  return { json: { ...item, testRunSkipped: true, testRunSkipReason: `Échec d'écriture : ${e.message}` } };
}

if (!item.testContainer) {
  return { json: { ...item, testFileWritten: true, testRunSkipped: true, testRunSkipReason: 'testContainer non fourni — test écrit mais pas exécuté' } };
}

// ── Exécution vitest sur CE fichier uniquement ──
function httpPostJson(hostname, port, urlPath, bodyObj) {
  return new Promise((resolve, reject) => {
    const bodyStr = JSON.stringify(bodyObj);
    const req = http.request({
      hostname, port, path: urlPath, method: 'POST',
      headers: { 'Authorization': 'Bearer ' + DOCKER_BRIDGE_TOKEN, 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(bodyStr) },
      timeout: 2 * 60 * 1000,
    }, (res) => {
      let data = '';
      res.on('data', chunk => { data += chunk; });
      res.on('end', () => {
        try { resolve(JSON.parse(data)); }
        catch (e) { reject(new Error(`Réponse non-JSON de docker-bridge (HTTP ${res.statusCode}) : ${data.substring(0, 300)}`)); }
      });
    });
    req.on('timeout', () => { req.destroy(new Error('Timeout docker-bridge')); });
    req.on('error', reject);
    req.write(bodyStr);
    req.end();
  });
}

let bridgeResponse;
try {
  bridgeResponse = await httpPostJson('docker-bridge', 3001, '/exec', {
    container: item.testContainer,
    args: ['npx', 'vitest', 'run', '--reporter=json', item.testFile.path],
  });
} catch (e) {
  return { json: { ...item, testFileWritten: true, testRunSkipped: true, testRunSkipReason: `docker-bridge injoignable : ${e.message}` } };
}

if (bridgeResponse.error) {
  return { json: { ...item, testFileWritten: true, testRunOk: false, testRunError: bridgeResponse.error } };
}

const stdout = bridgeResponse.stdout || '';
let parsed = null;
const jsonMatch = stdout.match(/\{[\s\S]*\}/);
if (jsonMatch) { try { parsed = JSON.parse(jsonMatch[0]); } catch (e) {} }

if (!parsed) {
  return { json: {
    ...item, testFileWritten: true, testRunOk: false,
    testRunError: 'Sortie Vitest non parsable pour ce fichier',
    testRunRaw: (stdout + (bridgeResponse.stderr || '')).substring(0, 1500),
  } };
}

const failures = [];
for (const suite of parsed.testResults ?? []) {
  for (const assertion of suite.assertionResults ?? []) {
    if (assertion.status === 'failed') {
      failures.push({
        test: assertion.fullName ?? assertion.title ?? '(nom inconnu)',
        message: (assertion.failureMessages ?? []).join('\n').substring(0, 800),
      });
    }
  }
}

return { json: {
  ...item,
  testFileWritten: true,
  testRunOk: true,
  testRunPassed: parsed.numPassedTests ?? 0,
  testRunFailed: parsed.numFailedTests ?? 0,
  testRunTotal:  parsed.numTotalTests ?? 0,
  testRunFailures: failures,
} };

// ═══════════════════════════════════════════════════════════
// 04m · MCP Tool Caller — appelle un serveur MCP en HTTP Streamable
// (JSON-RPC 2.0) directement. Handshake : initialize →
// notifications/initialized → tools/call. Gère les deux formats de
// réponse possibles (JSON simple OU flux SSE "data: {...}").
//
// Testé en direct contre mcp.vuetifyjs.com (2026-08-21) : le tool
// get_component_api_by_version attend "componentName", pas "component".
// ═══════════════════════════════════════════════════════════
const https = require('https');
const http  = require('http');
const { URL } = require('url');
const item  = $input.first().json;

const DEFAULT_MCP_URLS = {
  vuetify: 'https://mcp.vuetifyjs.com/mcp',
};
const mcpUrl = item.mcpServerUrl || DEFAULT_MCP_URLS[(item.uiLibrary ?? '').toLowerCase()];
if (!mcpUrl) {
  return [{ json: { ...item, extractionOk: false, extractionErrors: [`Aucune URL MCP connue pour "${item.uiLibrary}" — fournir "mcpServerUrl" explicitement.`] } }];
}

function mcpRequest(urlStr, bodyObj, sessionId) {
  return new Promise((resolve, reject) => {
    const u = new URL(urlStr);
    const client = u.protocol === 'https:' ? https : http;
    const bodyStr = JSON.stringify(bodyObj);
    const headers = {
      'Content-Type': 'application/json',
      'Accept': 'application/json, text/event-stream',
      'Content-Length': Buffer.byteLength(bodyStr),
    };
    if (sessionId) headers['Mcp-Session-Id'] = sessionId;
    if (item.mcpApiKey) headers['Authorization'] = `Bearer ${item.mcpApiKey}`;

    const req = client.request({
      hostname: u.hostname, port: u.port || (u.protocol === 'https:' ? 443 : 80),
      path: u.pathname + u.search, method: 'POST', headers,
      timeout: 20000,
    }, (res) => {
      let data = '';
      res.on('data', chunk => { data += chunk; });
      res.on('end', () => {
        const respSessionId = res.headers['mcp-session-id'] ?? sessionId ?? null;
        const contentType = res.headers['content-type'] ?? '';
        if (res.statusCode >= 400) {
          reject(new Error(`MCP HTTP ${res.statusCode}: ${data.substring(0, 300)}`));
          return;
        }
        if (!data.trim()) { resolve({ result: null, sessionId: respSessionId }); return; }
        if (contentType.includes('text/event-stream')) {
          const dataLines = data.split('\n').filter(l => l.startsWith('data:')).map(l => l.slice(5).trim());
          let parsed = null;
          for (const line of dataLines) { try { parsed = JSON.parse(line); } catch (e) {} }
          resolve({ result: parsed, sessionId: respSessionId });
        } else {
          try { resolve({ result: JSON.parse(data), sessionId: respSessionId }); }
          catch (e) { reject(new Error(`Réponse MCP non-JSON : ${data.substring(0, 300)}`)); }
        }
      });
    });
    req.on('timeout', () => req.destroy(new Error('Timeout serveur MCP')));
    req.on('error', reject);
    req.write(bodyStr);
    req.end();
  });
}

try {
  const initResp = await mcpRequest(mcpUrl, {
    jsonrpc: '2.0', id: 1, method: 'initialize',
    params: {
      protocolVersion: '2024-11-05',
      capabilities: {},
      clientInfo: { name: 'blackstaff', version: '1.0' },
    },
  }, null);
  const sessionId = initResp.sessionId;

  await mcpRequest(mcpUrl, { jsonrpc: '2.0', method: 'notifications/initialized', params: {} }, sessionId).catch(() => {});

  const toolName = 'get_component_api_by_version';
  const toolArgs = { componentName: item.sheetKey, version: item.libraryVersion ?? undefined };
  const callResp = await mcpRequest(mcpUrl, {
    jsonrpc: '2.0', id: 2, method: 'tools/call',
    params: { name: toolName, arguments: toolArgs },
  }, sessionId);

  const result = callResp.result?.result ?? callResp.result;
  if (!result) {
    return [{ json: { ...item, extractionOk: false, extractionErrors: ['Réponse MCP vide ou inattendue — voir logs pour ajuster le parsing.'] } }];
  }
  if (result.isError) {
    return [{ json: { ...item, extractionOk: false, extractionErrors: [`Le tool MCP a renvoyé une erreur : ${JSON.stringify(result.content ?? result).substring(0, 300)}`] } }];
  }

  const textBlock = (result.content ?? []).find(c => c.type === 'text');
  let apiData = textBlock?.text ?? result.content ?? result;
  if (typeof apiData === 'string') {
    try { apiData = JSON.parse(apiData); } catch (e) {}
  }

  const extractedSheet = {
    component: item.sheetKey,
    library: item.uiLibrary,
    version: item.libraryVersion ?? null,
    source: 'mcp',
    mcpServerUrl: mcpUrl,
    fetchedAt: new Date().toISOString(),
    api: apiData,
  };

  return [{ json: { ...item, extractedSheet, extractionErrors: [], extractionOk: true } }];
} catch (e) {
  return [{ json: { ...item, extractionOk: false, extractionErrors: [`Appel MCP échoué : ${e.message}`] } }];
}

// ═══════════════════════════════════════════════════════════
// 03f · OKF Concept Resolver — charge les conventions STABLES (routing
// Nuxt, structure CRUD, patterns d'intégration auth) depuis le bundle
// OKF sur disque, en résolvant un graphe de concepts markdown liés,
// profondeur limitée pour ne pas noyer le prompt.
//
// RÈGLES DE PRÉCÉDENCE STRICTES (jamais d'ambiguïté à l'exécution) :
//   1. .blackstaff/index.md (stack déclaré)   — jamais déduit
//   2. reference-sheets/ (03e, faits externes exacts)
//   3. okf/ (CE node — conventions stables, résolues par graphe)
//   4. taskTemplates (gabarits existants, fallback)
// Ce node NE lit AUCUNE config projet lui-même — okf/config/project.md
// N'EXISTE PAS, volontairement : .blackstaff/index.md reste la SEULE
// source de vérité pour les versions/stratégies déclarées, pour ne
// jamais réintroduire une deuxième source qui pourrait diverger.
//
// La classification de tâche est déterministe (regex/mots-clés), PAS
// un appel LLM — c'est une fonction pure, comme le mapping fichier→URL.
// ═══════════════════════════════════════════════════════════
const fs   = require('fs');
const path = require('path');
const item = $input.first().json;

const OKF_ROOT = `/home/node/projets/blackstaff/okf`;

function readOkfDoc(fullPath) {
  try {
    const raw = fs.readFileSync(fullPath, 'utf8');
    const m = raw.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
    if (!m) return { meta: {}, body: raw };
    const meta = {};
    for (const line of m[1].split('\n')) {
      const kv = line.match(/^(\w[\w.-]*)\s*:\s*(.*)$/);
      if (kv) meta[kv[1]] = kv[2].trim();
    }
    return { meta, body: m[2] };
  } catch (e) { return null; }
}

function extractLinks(body) {
  return [...body.matchAll(/\]\(([^)]+\.md[^)]*)\)/g)].map(m => m[1].split('#')[0]);
}

// Résolution de graphe profondeur limitée (défaut 2) — un concept
// pointe vers ses dépendances par lien markdown classique, comme dans
// le bundle fourni (ex: crud-frontend → frameworks/nuxt/v4.md#routing).
function normalizeOkfPath(p) {
  return p.replace(/^\/+/, ''); // '/frameworks/x.md' et 'frameworks/x.md' = le même concept
}

// `seen` est partagé entre TOUS les points d'entrée d'un même appel (pas
// un `seen` par entrée) — un concept référencé depuis deux entrées
// différentes n'est chargé qu'une seule fois, quel que soit le style de
// lien (absolu /x.md ou relatif x.md) utilisé dans le fichier source.
function resolveConcepts(entryRelPaths, depth, seen) {
  const stack = entryRelPaths.map(p => ({ p: normalizeOkfPath(p), d: 0 }));
  const parts = [];
  while (stack.length) {
    const { p, d } = stack.pop();
    if (seen.has(p) || d > depth) continue;
    seen.add(p);
    const full = path.join(OKF_ROOT, p);
    if (!full.startsWith(OKF_ROOT)) continue; // anti path-traversal
    const doc = readOkfDoc(full);
    if (!doc) continue;
    parts.push(`<!-- OKF: ${p} -->\n${doc.body.trim()}`);
    for (const link of extractLinks(doc.body)) stack.push({ p: normalizeOkfPath(link), d: d + 1 });
  }
  return parts.join('\n\n---\n\n');
}

// ── Classification déterministe de la tâche — AUCUN LLM ──
function classifyTask(it) {
  const filePath = it.currentFile?.path ?? '';
  const spec = (it.spec ?? '').toLowerCase();
  const fileList = it.fileList ?? [];
  const hasServerApi = fileList.some(f => /server\/api\//.test(f.path ?? '')) || /server\/api\//.test(filePath);
  const hasPages     = fileList.some(f => /\.vue$/.test(f.path ?? ''))       || filePath.endsWith('.vue');

  const tags = new Set();
  if (/server\/api\//.test(filePath))                      tags.add('api-route');
  if (filePath.endsWith('.vue'))                            tags.add('page');
  if (filePath.endsWith('.vue') && hasServerApi)            tags.add('page-consuming-api');
  if (hasServerApi && hasPages)                             tags.add('crud-complete');
  if (/connexion|login|inscription|s'inscrire|register|session|authent/i.test(spec)) tags.add('auth');
  if (tags.size === 0) tags.add('generic');
  return [...tags];
}

// ── Points d'entrée OKF par tag — ⚠️ chemins à ajuster une fois le
// bundle réel déployé sur disque (noms exacts de fichiers/dossiers
// non garantis identiques à cette convention par défaut). ──
const nuxtVersion = String(item.frontendContext?.version ?? '4').replace(/[^0-9]/g, '') || '4';

// ── Résolution des points d'entrée OKF par PATTERN DE CHEMIN EXACT ──
// Volontairement PAS de correspondance par tags seuls : plusieurs recettes
// (ex: route-index-get.md et route-delete.md) peuvent partager des tags
// identiques ([nuxt, api, crud, route]) sans être interchangeables — un
// "findEntry(type, tags)" qui prend le premier match serait ambigu.
// Chaque type de fichier généré pointe vers EXACTEMENT le bon concept.
function resolveOkfEntryPoints(it, tags) {
  const p = it.currentFile?.path ?? '';
  const entries = [];

  // Routes API — verbe HTTP + présence d'un segment dynamique juste avant
  // Un endpoint sous server/api/auth/ (ou dont la tâche est taguée 'auth')
  // n'est JAMAIS une route CRUD générique — évite de router login.post.ts
  // vers le pattern "création" juste parce que le verbe HTTP matche.
  const isAuthEndpoint = /server\/api\/auth\//i.test(p) || tags.includes('auth');
  const apiMatch = !isAuthEndpoint ? p.match(/server\/api\/.+\.(get|post|put|patch|delete)\.(ts|js)$/i) : null;
  if (apiMatch) {
    const verb = apiMatch[1].toLowerCase();
    const isDetail = /\[[^/\]]+\]\.\w+\.(ts|js)$/i.test(p);
    if (verb === 'get' && isDetail)      entries.push('patterns/crud-api/route-show-get.md');
    else if (verb === 'get')             entries.push('patterns/crud-api/route-index-get.md');
    else if (verb === 'post')            entries.push('patterns/crud-api/route-create-post.md');
    else if (verb === 'patch' || verb === 'put') entries.push('patterns/crud-api/route-update-patch.md');
    else if (verb === 'delete')          entries.push('patterns/crud-api/route-delete.md');
  }

  // Pages — nom de fichier exact
  if (p.endsWith('.vue')) {
    if (/\/(create|new|add)\.vue$/i.test(p))              entries.push('patterns/crud-frontend/page-create.md');
    else if (/\[[^/\]]+\]\/edit\.vue$/i.test(p) || /\/edit\.vue$/i.test(p)) entries.push('patterns/crud-frontend/page-edit.md');
    else if (/\[[^/\]]+\]\.vue$/i.test(p))                entries.push('patterns/crud-frontend/page-detail.md');
    else if (/\/index\.vue$/i.test(p))                    entries.push('patterns/crud-frontend/page-list.md');
  }

  // Conventions Nuxt de version — toujours pertinentes dès qu'un fichier
  // frontend ou une route API est concerné (chemin app/ vs racine, etc.)
  if (apiMatch || p.endsWith('.vue') || tags.includes('crud-complete')) {
    entries.push(`frameworks/nuxt/v${nuxtVersion}.md`);
  }

  // Auth — résolu par la stratégie DÉCLARÉE (.blackstaff/index.md), jamais
  // devinée. Sans authProvider déclaré, on charge quand même le pattern
  // BFF générique (toujours valide) mais aucune stratégie spécifique.
  if (tags.includes('auth')) {
    entries.push('integrations/nuxt-auth-utils/bff-proxy-pattern.md');
    const provider = (it.backendAuthProvider ?? '').toLowerCase();
    const STRATEGY_FILES = {
      'devise-jwt':          'integrations/nuxt-auth-utils/devise-jwt-pattern.md',
      'devise-token-auth':   'integrations/nuxt-auth-utils/devise-token-auth-pattern.md',
      'devise-session-csrf': 'integrations/nuxt-auth-utils/devise-session-csrf-pattern.md',
    };
    if (STRATEGY_FILES[provider]) entries.push(STRATEGY_FILES[provider]);
  }

  return [...new Set(entries)];
}

const taskTags = classifyTask(item);
const entryPoints = resolveOkfEntryPoints(item, taskTags);

let okfConventions = '';
let okfLoaded = false;
if (fs.existsSync(OKF_ROOT) && entryPoints.length > 0) {
  okfConventions = resolveConcepts(entryPoints, 2, new Set());
  okfLoaded = okfConventions.length > 0;
}

// ── Extension de resolvedMarkdownContext existant (pas de remplacement,
// pas de nouveau champ à câbler ailleurs) ──
const mergedMarkdownContext = [item.resolvedMarkdownContext, okfConventions]
  .filter(Boolean).join('\n\n═══════════════════\n\n');

return [{ json: { ...item, resolvedMarkdownContext: mergedMarkdownContext, taskTags, okfLoaded } }];

// ═══════════════════════════════════════════════════════════
// 02v · Review Result Recorder — enregistre UN événement de review
// (local Ollama OU Claude, après escalade) pour une tâche donnée.
// Écrit à deux endroits :
//   - fichier PAR TÂCHE (reviews/<taskId>.json) : historique complet
//     de cette tâche, consommé par get-review-summary
//   - journal GLOBAL (reviews-global.jsonl, append-only) : tous
//     projets/tâches confondus, pour repérer un motif d'erreur qui
//     revient souvent -> signe d'un mécanisme manquant dans le
//     pipeline de génération (pas juste un accident isolé).
// ═══════════════════════════════════════════════════════════
const fs   = require('fs');
const path = require('path');
const item = $input.first().json.body ?? $input.first().json;

const REQUIRED = ['project', 'taskId', 'file', 'source', 'passed'];
for (const field of REQUIRED) {
  if (item[field] === undefined || item[field] === null) {
    throw new Error(`[RECORD-REVIEW-RESULT] champ requis manquant : "${field}"`);
  }
}
// 'qwen-direct' = a piece generated by the decomposed local path of hybrid-dev-loop (not Blackstaff)
if (!['local', 'claude', 'qwen-direct'].includes(item.source)) {
  throw new Error(`[RECORD-REVIEW-RESULT] "source" doit être "local", "claude" ou "qwen-direct", reçu "${item.source}"`);
}

// ── Classification déterministe de la raison — pour le regroupement en
// motifs récurrents côté get-review-summary, pas une nouvelle détection. ──
function classifyReason(reason) {
  if (!reason) return 'inconnu';
  const r = String(reason).toLowerCase();
  if (r.includes('backend attendu') || r.includes('table de routage') || r.includes('endpoint') || r.includes('app/ alors que')) return 'violation_contrat';
  if (r.includes('placeholder') || r.includes('hypothétique') || r.includes('todo') || r.includes('remplacer par une vraie'))  return 'code_placeholder';
  if (r.includes('import interdit'))                                          return 'import_interdit';
  if (r.includes('sfc invalide') || r.includes('<template>') || r.includes('<script>')) return 'structure_vue_invalide';
  if (r.includes('accolades'))                                                return 'syntaxe_accolades';
  if (r.includes("n'est pas importé") || r.includes('middleware'))            return 'middleware_mal_reference';
  if (r.includes("n'existe pas dans les exports") || r.includes('fantôme'))   return 'reference_fantome';
  return 'autre';
}

const PROJECTS_ROOT = `/home/node/projets/`;
// project is a path relative to ~/Projects/Perso (e.g. "candlekeep/candlekeep-backend"): keep its "/" —
// stripping them wrote reviews under a non-existent "candlekeepcandlekeep-backend" folder — but refuse
// anything else (no "..", no absolute path).
const project = String(item.project);
if (!/^[a-zA-Z0-9_-]+(\/[a-zA-Z0-9_-]+)*$/.test(project)) throw new Error(`[REVIEW] "project" invalide : "${project}"`);
if (!project) throw new Error('[RECORD-REVIEW-RESULT] "project" invalide après nettoyage');
const taskId = String(item.taskId).replace(/[^a-zA-Z0-9_-]/g, '');
if (!taskId) throw new Error('[RECORD-REVIEW-RESULT] "taskId" invalide après nettoyage');

const reviewsDir = path.join(PROJECTS_ROOT, project, '.blackstaff', 'reviews');
const taskFilePath = path.join(reviewsDir, `${taskId}.json`);
const globalLogPath = path.join(PROJECTS_ROOT, 'blackstaff', 'review-log.jsonl');

const entry = {
  ts: new Date().toISOString(),
  file: item.file,
  source: item.source,          // 'local' | 'claude' | 'qwen-direct'
  score: item.score ?? null,
  passed: !!item.passed,
  reason: item.reason ?? null,
  reasonCategory: item.reasonCategory || classifyReason(item.reason), // the caller's category wins
  retryCount: item.retryCount ?? 0,
};

// ── Fichier par tâche (lecture-modification-écriture — usage séquentiel
// attendu, pas de verrou : deux écritures concurrentes sur la MÊME tâche
// au MÊME instant ne sont pas garanties, cas très improbable ici). ──
fs.mkdirSync(reviewsDir, { recursive: true });
let taskEntries = [];
if (fs.existsSync(taskFilePath)) {
  try { taskEntries = JSON.parse(fs.readFileSync(taskFilePath, 'utf8')); } catch (e) { taskEntries = []; }
}
taskEntries.push(entry);
fs.writeFileSync(taskFilePath, JSON.stringify(taskEntries, null, 2), 'utf8');

// ── Journal global (append-only JSONL — jamais réécrit en entier) ──
fs.mkdirSync(path.dirname(globalLogPath), { recursive: true });
fs.appendFileSync(globalLogPath, JSON.stringify({ project, taskId, ...entry }) + '\n', 'utf8');

// Tally immédiat de la tâche (pratique pour un affichage live côté client,
// sans devoir appeler get-review-summary après chaque événement).
const filesInTask = [...new Set(taskEntries.map(e => e.file?.path).filter(Boolean))];
const passedFiles = filesInTask.filter(fp => {
  const lastForFile = [...taskEntries].reverse().find(e => e.file?.path === fp);
  return lastForFile?.passed;
});

return [{ json: {
  recorded: true,
  taskFilePath,
  runningTally: {
    totalFiles: filesInTask.length,
    passedFiles: passedFiles.length,
    totalEvents: taskEntries.length,
  },
} }];

// ═══════════════════════════════════════════════════════════
// 02w · Review Summary Builder — récap complet d'une tâche : par
// fichier (dernier statut, nb de tentatives, escaladé à Claude ou
// pas) ET global (score moyen, taux de réussite locale vs Claude).
// Ajoute une section "motifs récurrents" en scannant le journal
// GLOBAL (toutes tâches/projets) — sert à repérer un type d'erreur
// qui revient souvent, signe possible d'un mécanisme manquant dans
// le pipeline de génération plutôt qu'un accident isolé.
// ═══════════════════════════════════════════════════════════
const fs   = require('fs');
const path = require('path');
const item = $input.first().json.body ?? $input.first().json;

if (!item.project) throw new Error('[GET-REVIEW-SUMMARY] "project" requis');
if (!item.taskId)  throw new Error('[GET-REVIEW-SUMMARY] "taskId" requis');

const PROJECTS_ROOT = `/home/node/projets/`;
// project is a path relative to ~/Projects/Perso (e.g. "candlekeep/candlekeep-backend"): keep its "/" —
// stripping them wrote reviews under a non-existent "candlekeepcandlekeep-backend" folder — but refuse
// anything else (no "..", no absolute path).
const project = String(item.project);
if (!/^[a-zA-Z0-9_-]+(\/[a-zA-Z0-9_-]+)*$/.test(project)) throw new Error(`[REVIEW] "project" invalide : "${project}"`);
const taskId  = String(item.taskId).replace(/[^a-zA-Z0-9_-]/g, '');

const taskFilePath  = path.join(PROJECTS_ROOT, project, '.blackstaff', 'reviews', `${taskId}.json`);
const globalLogPath = path.join(PROJECTS_ROOT, 'blackstaff', 'review-log.jsonl');

if (!fs.existsSync(taskFilePath)) {
  return [{ json: { found: false, reason: `Aucun historique de review pour la tâche "${taskId}" (projet "${project}").` } }];
}

let entries = [];
try { entries = JSON.parse(fs.readFileSync(taskFilePath, 'utf8')); } catch (e) {
  return [{ json: { found: false, reason: `Fichier d'historique corrompu : ${e.message}` } }];
}

// ── Récap PAR FICHIER — dernier événement fait foi pour le statut final,
// mais on garde le compte total de tentatives et si Claude a été sollicité. ──
const filePaths = [...new Set(entries.map(e => e.file?.path).filter(Boolean))];
const perFile = filePaths.map(fp => {
  const fileEvents = entries.filter(e => e.file?.path === fp);
  const last = fileEvents[fileEvents.length - 1];
  return {
    path: fp,
    finalPassed: !!last?.passed,
    finalScore: last?.score ?? null,
    finalSource: last?.source ?? null,
    attempts: fileEvents.length,
    escalatedToClaude: fileEvents.some(e => e.source === 'claude'),
    reasonHistory: fileEvents.filter(e => !e.passed).map(e => ({ source: e.source, reason: e.reason, category: e.reasonCategory })),
  };
});

// ── Récap GLOBAL de la tâche ──
const totalFiles = perFile.length;
const passedFinal = perFile.filter(f => f.finalPassed).length;
const passedLocalOnly = perFile.filter(f => f.finalPassed && !f.escalatedToClaude).length;
const escalated = perFile.filter(f => f.escalatedToClaude).length;
const stillFailing = perFile.filter(f => !f.finalPassed);
const scores = perFile.map(f => f.finalScore).filter(s => s !== null);
const averageScore = scores.length > 0 ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length) : null;

const taskSummary = {
  totalFiles,
  passedFinal,
  passedLocalOnly,       // jamais eu besoin de Claude — le signal le plus positif sur le pipeline
  escalatedToClaude: escalated,
  stillFailing: stillFailing.map(f => ({ path: f.path, lastReason: f.reasonHistory[f.reasonHistory.length - 1] ?? null })),
  averageScore,
};

// ── Motifs récurrents — scan du journal GLOBAL (toutes tâches/projets),
// capé aux N dernières lignes pour rester borné en taille/temps. Un motif
// qui revient sur PLUSIEURS tâches distinctes (pas juste plusieurs fois
// dans la même) est le signal le plus fort d'un mécanisme manquant. ──
let systemicPatterns = [];
if (fs.existsSync(globalLogPath)) {
  const MAX_LINES = 3000;
  const raw = fs.readFileSync(globalLogPath, 'utf8').trim();
  const allLines = raw ? raw.split('\n') : [];
  const recentLines = allLines.slice(-MAX_LINES);
  const globalEntries = recentLines.map(l => { try { return JSON.parse(l); } catch (e) { return null; } }).filter(Boolean);

  const byCategory = {};
  for (const e of globalEntries) {
    if (e.passed) continue; // seuls les échecs comptent pour un motif récurrent
    const cat = e.reasonCategory ?? 'autre';
    byCategory[cat] = byCategory[cat] ?? { count: 0, taskIds: new Set(), example: e.reason };
    byCategory[cat].count += 1;
    byCategory[cat].taskIds.add(e.taskId);
  }
  systemicPatterns = Object.entries(byCategory)
    .map(([category, v]) => ({ category, occurrences: v.count, distinctTasks: v.taskIds.size, example: v.example }))
    .filter(p => p.distinctTasks >= 2) // récurrent = vu sur AU MOINS 2 tâches différentes
    .sort((a, b) => b.distinctTasks - a.distinctTasks);
}

return [{ json: {
  found: true,
  project, taskId,
  perFile,
  taskSummary,
  systemicPatterns, // vide = rien de récurrent détecté sur les dernières tâches
} }];

// ═══════════════════════════════════════════════════════════
// 04c2 · Plan Review Prompt Builder — ne tourne QUE si 04c (déterministe)
// n'a RIEN trouvé (voir 04c1). Demande au MÊME modèle local une relecture
// ciblée sur ce que le regex ne peut pas couvrir : cohérence entre
// l'objectif déclaré et le périmètre réel du plan. Ne remplace PAS la
// review Claude côté client — sert à réduire la fréquence d'escalade en
// filtrant les cas qu'un second passage, même sur le même modèle, attrape
// (angle de lecture différent : critique plutôt que génération).
// ═══════════════════════════════════════════════════════════
const item = $input.first().json;

const systemPrompt = `Tu relis un plan de génération de code pour vérifier UNE SEULE chose :
est-ce que le PÉRIMÈTRE RÉEL du plan (les fichiers et ce qu'ils exposent) correspond
EXACTEMENT à l'OBJECTIF déclaré — ni plus, ni moins.

Réponds STRICTEMENT en JSON, sans texte autour :
{ "ok": true }
ou
{ "ok": false, "issues": ["raison précise 1", "raison précise 2"] }

Cherche SPÉCIFIQUEMENT :
- Une opération exposée (create/update/remove/delete) qui n'a AUCUN fichier
  consommateur dans le plan (page/composant qui l'utilise réellement).
- Un fichier prévu (composant, page) qui n'est utilisé par AUCUN autre fichier
  du plan — orphelin.
- Un périmètre plus large que ce que l'objectif décrit (ex: objectif "afficher
  la liste" mais le plan inclut création/édition/suppression).
- Un périmètre plus étroit qui laisse l'objectif inatteignable.

Ne remonte PAS de style, de nommage, ou de préférence — uniquement une
incohérence de PÉRIMÈTRE entre l'objectif et les fichiers listés.`.trim();

const userPrompt = `## Objectif déclaré\n\n${item.generatedTitle ?? ''}\n\n` +
  `${item.functionalAnalysis?.goal ?? ''}\n\n` +
  `## Plan (fichiers et ce qu'ils exposent)\n\n${item.generatedDescription ?? ''}`;

return [{ json: { ...item, systemPrompt, userPrompt } }];

// ═══════════════════════════════════════════════════════════
// 04c3 · Plan Review Parser — fusionne les issues trouvées par le LLM
// local dans planValidationIssues (MÊME champ que les checks 04c
// déterministes) — le client n'a rien de nouveau à gérer, il continue
// de lire un seul champ, peu importe la source de l'issue.
// ═══════════════════════════════════════════════════════════
const item = $input.first().json;

function tryParseJson(text) {
  if (!text) return null;
  try { return JSON.parse(text); } catch (e) {}
  const m = text.match(/\{[\s\S]*\}/);
  if (!m) return null;
  try { return JSON.parse(m[0].replace(/,(\s*[}\]])/g, '$1')); } catch (e) { return null; }
}

const raw = (typeof item.text === 'string' ? item.text : null) ?? item.response ?? '';
const parsed = tryParseJson(raw);

const llmIssues = (parsed && parsed.ok === false && Array.isArray(parsed.issues))
  ? parsed.issues.map(i => `[review locale] ${i}`)
  : [];

const mergedIssues = [...(item.planValidationIssues ?? []), ...llmIssues];

return [{ json: {
  ...item,
  planValidationIssues: mergedIssues,
  planLlmReviewRan: true,
  planLlmReviewFoundIssues: llmIssues.length > 0,
} }];

// ═══════════════════════════════════════════════════════════
// 02x · Reference Sources Lister — lit le manifeste des sources à
// rafraîchir (reference-sheets/sources.json, racine partagée blackstaff)
// et le renvoie tel quel. Aucun LLM ici — le client boucle dessus et
// appelle "update-reference-sheet" une fois par entrée, exactement
// comme il boucle déjà sur les fichiers à générer.
// ═══════════════════════════════════════════════════════════
const fs   = require('fs');
const path = require('path');

const BLACKSTAFF_ROOT = `/home/node/projets/blackstaff/`;
const sourcesPath = path.join(BLACKSTAFF_ROOT, 'reference-sheets', 'sources.json');

if (!fs.existsSync(sourcesPath)) {
  return [{ json: {
    referenceSources: [],
    referenceSourcesError: `Aucun manifeste trouvé à ${sourcesPath} — crée-le avec un tableau ` +
      `d'entrées { sheetType, sheetKey, docsUrl } (ou uiLibrary/libraryVersion pour ui-component).`,
  } }];
}

let sources;
try {
  sources = JSON.parse(fs.readFileSync(sourcesPath, 'utf8'));
} catch (e) {
  return [{ json: { referenceSources: [], referenceSourcesError: `Manifeste invalide (JSON cassé) : ${e.message}` } }];
}

if (!Array.isArray(sources)) {
  return [{ json: { referenceSources: [], referenceSourcesError: 'Le manifeste doit être un tableau JSON.' } }];
}

// Validation légère de chaque entrée — une entrée invalide est signalée
// mais ne bloque pas les autres.
const valid = [];
const invalid = [];
for (const s of sources) {
  const isUiComponent = s.sheetType === 'ui-component';
  const ok = s.sheetType && s.sheetKey && (isUiComponent ? s.uiLibrary : s.docsUrl);
  if (ok) { valid.push(s); } else { invalid.push(s); }
}

return [{ json: {
  referenceSources: valid,
  referenceSourcesError: invalid.length > 0
    ? `${invalid.length} entrée(s) ignorée(s) (champs manquants) : ${JSON.stringify(invalid)}`
    : null,
} }];

const DOCKER_BRIDGE_TOKEN = require('fs').readFileSync('/run/secrets/docker-bridge-token', 'utf8').trim();
// ═══════════════════════════════════════════════════════════
// 07c · Spec Check — contrôle mécanique d'une spec RSpec générée (ajouté le 2026-10-01)
// Exécute llm-specialists/_shared/scripts/rspec_pitfalls.rb DANS le conteneur du projet (via docker-bridge),
// sur une copie de la spec sous tmp/bs-check/ (jamais dans spec/), avec la table `bin/rails routes` en cache 1 h.
// Mesures : 0 fausse alarme sur les 108 vraies specs de candlekeep ; ~1 spec rouge sur 2 à 1 sur 6 attrapée
// selon le ticket. Chaque constat porte un `hint` prêt à servir de diagnostic pour une nouvelle tentative.
// Ne bloque rien : ajoute `specCheck` à la réponse et des issues `spec_pitfall`. Activé seulement si le projet
// déclare `checkContainer` (stack.backend dans .blackstaff/index.md) et que le fichier est une spec Ruby.
// ═══════════════════════════════════════════════════════════
const fs = require('fs');
const http = require('http');
const item = $input.first().json;
const CHECKER = '/home/node/projets/llm-specialists/_shared/scripts/rspec_pitfalls.rb';

const file = (item.generatedFiles ?? [])[0];
const container = item.checkContainer ?? item.backendContext?.checkContainer ?? null;
const isSpec = file?.path && /(^|\/)spec\/.+_spec\.rb$/.test(file.path);
if (!item.options?.taskMode || (item.step && item.step !== 'generate') || !isSpec || !container || !file.content?.trim()) {
  return [{ json: { ...item, specCheck: { ran: false, reason: !container ? 'no checkContainer declared' : 'not a generated Ruby spec' } } }];
}

function post(bodyObj) {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify(bodyObj);
    const req = http.request({ hostname: 'docker-bridge', port: 3001, path: '/exec', method: 'POST', timeout: 120000,
      headers: { 'Authorization': 'Bearer ' + DOCKER_BRIDGE_TOKEN, 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) } }, (res) => {
      let data = ''; res.on('data', c => { data += c; });
      res.on('end', () => { try { resolve(JSON.parse(data)); } catch (e) { reject(new Error(`docker-bridge non-JSON: ${data.slice(0, 200)}`)); } });
    });
    req.on('timeout', () => req.destroy(new Error('docker-bridge timeout')));
    req.on('error', reject); req.write(body); req.end();
  });
}

const b64 = (s) => Buffer.from(s, 'utf8').toString('base64');
const rel = `tmp/bs-check/${file.path.replace(/^\/+/, '')}`;  // keeps "spec/requests/..." in the path
const script = [
  'set -e', 'd=tmp/bs-check', `mkdir -p "$(dirname '${rel}')"`,
  `printf %s '${b64(fs.readFileSync(CHECKER, 'utf8'))}' | base64 -d > $d/rspec_pitfalls.rb`,
  `printf %s '${b64(file.content)}' | base64 -d > '${rel}'`,
  'if [ ! -s $d/routes.txt ] || [ -n "$(find $d/routes.txt -mmin +60)" ]; then bin/rails routes > $d/routes.txt 2>/dev/null || true; fi',
  `ruby $d/rspec_pitfalls.rb --routes $d/routes.txt . '${rel}' || true`,
].join('; ');

let findings = [], error = null;
try {
  const res = await post({ container, args: ['bash', '-c', script] });
  if (res.error) throw new Error(res.error);
  const parsed = JSON.parse(res.stdout || '{}');
  findings = parsed[rel] ?? [];
  if (!Array.isArray(findings)) { error = findings.message ?? 'checker error'; findings = []; }
} catch (e) {
  error = e.message;
}

const errors = findings.filter(f => f.severity !== 'warning');
const specCheck = { ran: !error, ok: !error && errors.length === 0, container, findings, error,
  hints: [...new Set(errors.map(f => f.hint))] };
const response = item.response ? { ...item.response, meta: { ...item.response.meta,
  issues: [...(item.response.meta?.issues ?? []), ...errors.map(f => ({ type: 'spec_pitfall', message: `l.${f.line} ${f.kind}: ${f.message}` }))],
  hasIssues: (item.response.meta?.hasIssues ?? false) || errors.length > 0 } } : item.response;
return [{ json: { ...item, response, specCheck, hasIssues: (item.hasIssues ?? false) || errors.length > 0 } }];

// ═══════════════════════════════════════════════════════════
// 07m · Merge Check — compare le fichier généré à existingContent avant écriture (ajouté le 2026-10-02)
// Pourquoi : sur le ticket #97, chargé d'AJOUTER des exemples à une spec existante, Blackstaff a réécrit une ligne
// existante sans rapport ("X-Total-Pages" -> "X-Total-PAGES") 2 fois sur 2, et un retry a cassé un stub existant
// (api/components/search -> api/components_search) ; les specs restaient vertes, seule la relecture l'a vu.
// - toujours (fichier existant fourni) : `mergeCheck` liste chaque ligne existante supprimée ou modifiée (avant/après),
//   et une issue `merge_altered_existing` est ajoutée ; mesuré sur les 6 fusions du ticket #97 : 0 fausse alerte
//   sur les 3 fusions légitimes, les 3 altérations parasites signalées.
// - `mergePolicy: "additive"` dans la requête (tâche « ajoute sans toucher à l'existant ») : les lignes existantes
//   altérées sont remises telles quelles, seuls les ajouts sont gardés, puis le fichier est écrit.
//   Ne pas l'utiliser pour un retry : là, modifier l'existant est le but.
// Refuse d'écrire (error + generatedFiles vide) si le fichier existant a été coupé dans le prompt, ou si la réponse
// semble tronquée (voir plus bas).
// Source et test hors ligne : llm-specialists/_shared/n8n/blackstaff/merge_check.js, test_merge_check.js.
// ═══════════════════════════════════════════════════════════
const item = $input.first().json;
const file = (item.generatedFiles ?? [])[0];
if (!item.options?.taskMode || (item.step && item.step !== 'generate') || !item.existingContent || !file?.content || item.error) {
  return [{ json: { ...item, mergeCheck: { ran: false } } }];
}

// Refuse 1 (2026-10-02): the existing file was cut in the prompt (05t, section 'fichier existant'): the model never
// saw its end and would drop it. Nothing is written.
const cut = (item.promptTruncations ?? []).find((t) => t.section === 'fichier existant');
if (cut) {
  return [{ json: { ...item, generatedFiles: [], mergeCheck: { ran: true, refused: 'existing_content_truncated' },
    error: `existing_content_truncated: le fichier existant fait ${cut.length} caractères, le prompt n'en a transmis que ${cut.kept} ; rien n'est écrit (découper la tâche ou éditer ce fichier à la main)` } }];
}

function mergeCheck(existing, generated, policy) {
  const norm = (t) => (t ?? '').replace(/\r\n/g, '\n').split('\n').map((l) => l.replace(/\s+$/, ''));
  const trimTail = (a) => { const r = a.slice(); while (r.length && r[r.length - 1] === '') r.pop(); return r; };
  const a = trimTail(norm(existing));
  let b = trimTail(norm(generated));
  // the formatter keeps a leading "# path/to/file.rb" comment when the model wrote one: not part of the merge
  if (b.length && /^\s*(#|\/\/)\s*\S+\.\w+\s*$/.test(b[0]) && !(a.length && a[0] === b[0])) b = b.slice(1);

  // LCS table on lines (files are a few hundred lines: O(n*m) is fine)
  const n = a.length, m = b.length;
  const dp = Array.from({ length: n + 1 }, () => new Int32Array(m + 1));
  for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--) {
    dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
  }
  // walk the alignment: '=' kept, '-' existing line not kept, '+' inserted line
  const ops = [];
  let i = 0, j = 0;
  while (i < n || j < m) {
    if (i < n && j < m && a[i] === b[j]) { ops.push(['=', i, j]); i++; j++; }
    else if (j < m && (i >= n || dp[i][j + 1] >= dp[i + 1][j])) { ops.push(['+', null, j]); j++; }
    else { ops.push(['-', i, null]); i++; }
  }

  // group consecutive non-'=' ops into hunks; a hunk with '-' lines alters existing content
  const altered = [];
  const hunks = [];
  let cur = null;
  for (const op of ops) {
    if (op[0] === '=') { if (cur) { hunks.push(cur); cur = null; } continue; }
    if (!cur) cur = { del: [], ins: [] };
    if (op[0] === '-') cur.del.push(op[1]); else cur.ins.push(op[2]);
  }
  if (cur) hunks.push(cur);
  for (const h of hunks) {
    if (!h.del.length) continue;
    altered.push({
      line: h.del[0] + 1,
      before: h.del.map((k) => a[k]).join('\n'),
      after: h.ins.length ? h.ins.map((k) => b[k]).join('\n') : null,
    });
  }
  const inserted = ops.filter((o) => o[0] === '+').length;
  const result = { ran: true, policy: policy === 'additive' ? 'additive' : 'report', insertedLines: inserted, alteredExisting: altered, restored: false };

  if (result.policy === 'additive' && altered.length) {
    // rebuild = every existing line, in order, plus the inserted lines that are genuinely new. In a hunk that
    // replaced existing lines, an inserted line that resembles a deleted one (bigram Dice >= 0.5) is its rewrite
    // and is dropped; the other inserted lines of that hunk are kept, after the restored existing lines.
    const bigrams = (t) => { const s = t.trim(); const g = new Map(); for (let k = 0; k < s.length - 1; k++) { const x = s.slice(k, k + 2); g.set(x, (g.get(x) || 0) + 1); } return g; };
    const dice = (x, y) => {
      const gx = bigrams(x), gy = bigrams(y); let inter = 0, nx = 0, ny = 0;
      for (const v of gx.values()) nx += v; for (const v of gy.values()) ny += v;
      for (const [k, v] of gx) inter += Math.min(v, gy.get(k) || 0);
      return nx + ny ? (2 * inter) / (nx + ny) : 1;
    };
    const rewrites = new Set();
    for (const h of hunks) {
      if (!h.del.length) continue;
      for (const d of h.del) {
        let best = null, bestScore = 0.5;
        for (const k of h.ins) { if (rewrites.has(k)) continue; const sc = dice(a[d], b[k]); if (sc >= bestScore) { best = k; bestScore = sc; } }
        if (best !== null) rewrites.add(best);
      }
    }
    const lines = [];
    let pending = [];
    for (const op of ops) {
      if (op[0] === '+') { if (!rewrites.has(op[2])) pending.push(b[op[2]]); continue; }
      if (op[0] === '-') { lines.push(a[op[1]]); continue; }
      lines.push(...pending); pending = []; lines.push(a[op[1]]);
    }
    lines.push(...pending);
    result.restored = true;
    result.droppedRewrites = rewrites.size;
    result.content = lines.join('\n') + '\n';
  }
  return result;
}

const policy = item.mergePolicy === 'additive' ? 'additive' : 'report';
const check = mergeCheck(item.existingContent, file.content, policy);
const { content: restoredContent, ...summary } = check;
// Refuse 2 (2026-10-02): output that looks cut off (the generator's finishReason is not reported): more than half of
// the existing lines gone AND the generated file under 60 % of the existing one. A restored (additive) file is whole.
const lineCount = (t) => (t ?? '').split('\n').length;
const deletedLines = check.alteredExisting.reduce((n, x) => n + x.before.split('\n').length, 0);
if (!check.restored && deletedLines > 0.5 * lineCount(item.existingContent) && lineCount(file.content) < 0.6 * lineCount(item.existingContent)) {
  return [{ json: { ...item, generatedFiles: [], mergeCheck: { ...summary, refused: 'suspected_truncated_output' },
    error: `suspected_truncated_output: ${deletedLines} lignes existantes sur ${lineCount(item.existingContent)} ont disparu et le fichier généré ne fait que ${lineCount(file.content)} lignes ; rien n'est écrit` } }];
}
const issues = [...(item.response?.meta?.issues ?? [])];
let generatedFiles = item.generatedFiles;
if (check.alteredExisting.length) {
  issues.push({
    type: check.restored ? 'merge_restored' : 'merge_altered_existing',
    message: (check.restored ? 'Lignes existantes remises en place : ' : 'Lignes existantes modifiées ou supprimées : ') +
      check.alteredExisting.map((x) => 'L' + x.line).join(', '),
  });
}
if (check.restored) {
  generatedFiles = [{ ...file, content: restoredContent }, ...item.generatedFiles.slice(1)];
}
const response = item.response ? { ...item.response, meta: { ...item.response.meta, issues, hasIssues: issues.length > 0 } } : item.response;
return [{ json: { ...item, generatedFiles, response, hasIssues: item.hasIssues || check.alteredExisting.length > 0, mergeCheck: summary } }];

// ═══════════════════════════════════════════════════════════
// 04b2 · Rails Planner Rules — 04b's prompt was written for Nuxt
// (fixed shared/types + composable + form.vue structures). For a
// Rails project, swap those Nuxt-only blocks for Rails equivalents.
// Any other framework passes through untouched.
// ═══════════════════════════════════════════════════════════
const item = $input.first().json;
if (!/rails/i.test(item.framework ?? '') || typeof item.systemPrompt !== 'string') {
  return [{ json: item }];
}

const RAILS_RULES = `⚠️ RÈGLE MÉCANIQUE, PAS UN CHOIX — regarde le champ "objectLifecycle" de l'analyse
fonctionnelle ci-dessous. Projet Rails API : la logique métier vit dans des services
namespacés (app/services/<namespace>/<action>_service.rb, classe <Namespace>::<Action>Service
< ApplicationService) qui renvoient un ServiceResult via success(data) / failure(errors)
— jamais d'exception pour un échec métier attendu. Les contrôleurs restent minces.
Un workflow qui enchaîne plusieurs services passe par une Procedure
(app/procedures/<namespace>/<nom>_procedure.rb).
- objectLifecycle === "ephemeral" → "crud" est EXCLU dans tous les cas : pas de modèle,
  pas de migration, pas de serializer, pas d'actions index/show/update/destroy. Structure
  minimale — 2 fichiers, ni plus ni moins :
  1. app/services/<namespace>/<action>_service.rb : le service qui applique la règle
     métier et renvoie success(...) / failure([...]).
  2. spec/services/<namespace>/<action>_service_spec.rb : la spec RSpec du service
     (cas nominal + chaque cas d'échec métier).
  Ajoute un contrôleur (app/controllers/api/v1/...) + sa route + une spec de requête
  (spec/requests/...) UNIQUEMENT si l'instruction demande explicitement un endpoint HTTP.
- objectLifecycle === "persisted" MAIS l'utilisateur ne crée/modifie/supprime PAS
  lui-même la ressource (valeur calculée, compteur automatique, synchronisation) →
  PAS de CRUD complet. "patterns": []. Le service qui calcule/modifie la valeur
  persistée + sa spec ; modèle et migration SEULEMENT si la donnée n'existe pas encore ;
  endpoint SEULEMENT s'il est demandé.
- objectLifecycle === "persisted" ET l'utilisateur gère lui-même la ressource → CRUD
  si le gabarit "crud" est fourni : modèle + migration, services Create/Update/Delete
  namespacés, contrôleur api/v1 mince qui délègue aux services, serializer si le
  projet en déclare un, specs (modèle, services, requêtes).
- N'utilise JAMAIS de fichiers frontend (.vue, .ts, composables, pages, zod) dans un
  plan Rails : ce dépôt est l'API seule.

`;
const RAILS_AUTH = `⚠️ L'authentification est déjà assurée globalement par ApplicationController
(before_action :authenticate_devise_api_token!). Ne crée AUCUN fichier d'auth pour une
tâche qui ne parle pas explicitement de connexion/session. Un endpoint qui doit rester
public le mentionne explicitement dans sa description (skip_before_action).

`;
const RAILS_SYMMETRY = `- Chaque service exposé DOIT être appelé par un fichier du plan (contrôleur,
  job, procedure) OU être explicitement demandé seul par l'instruction.`;
const RAILS_EXAMPLE = `{"patterns":[],"patternJustification":"calcul ponctuel sans persistance, un service suffit","entities":["Invoice"],"files":[{"path":"app/services/invoices/total_service.rb","category":"Services","description":"Invoices::TotalService < ApplicationService : initialize(lines:), call renvoie success(total) ou failure([\\"lines is empty\\"])","exports":["Invoices::TotalService"],"externalApisUsed":[]},{"path":"spec/services/invoices/total_service_spec.rb","category":"Specs","description":"cas nominal + liste vide","exports":[],"externalApisUsed":[]}],"implementationSteps":["Créer le service","Écrire sa spec"]}`;

// Replace the text between two markers (start included, end excluded).
const between = (text, start, end, replacement) => {
  const a = text.indexOf(start);
  const b = text.indexOf(end, a + 1);
  if (a < 0 || b < 0) throw new Error('04b2: marker not found in 04b prompt: ' + (a < 0 ? start : end));
  return text.slice(0, a) + replacement + text.slice(b);
};
const replaceOnce = (text, from, to) => {
  if (!text.includes(from)) throw new Error('04b2: text not found in 04b prompt: ' + from.slice(0, 60));
  return text.replace(from, () => to);
};

let p = item.systemPrompt;
p = replaceOnce(p, '(ex: pages/, server/api/, composables/, app/ —',
  '(ex: app/services/<namespace>/, app/controllers/api/v1/, app/models/, db/migrate/, spec/services/, spec/requests/ —');
p = replaceOnce(p, '(ex: "Objet éphémère à 4 champs\nou moins, un composable réactif simple suffit, pas de CRUD ni de Builder justifié")',
  '(ex: "Opération ponctuelle sans persistance, un service simple suffit, pas de CRUD justifié")');
p = between(p, '⚠️ RÈGLE MÉCANIQUE, PAS UN CHOIX', '⚠️ NE CHOISIS JAMAIS un gabarit', RAILS_RULES);
p = between(p, '⚠️ Si une page est protégée par le pattern auth (middleware)', '## Règle de périmètre', RAILS_AUTH);
p = between(p, '- Chaque fichier qui appelle une API (mention de $fetch/useFetch', '\n\nAvant de répondre', RAILS_SYMMETRY);
const exStart = p.indexOf('{"patterns":["crud"],"patternJustification":"gestion complète');
if (exStart < 0) throw new Error('04b2: format example not found in 04b prompt');
p = p.slice(0, exStart) + RAILS_EXAMPLE;

return [{ json: { ...item, systemPrompt: p, contextDebug: { ...(item.contextDebug || {}), railsPlannerRules: true } } }];
